    internal static int TbWideCells(emon.Port.Cells tc, int cfirst, int cend, emon.Port.Cells wd, emon.Port.Cells tw) {
        // How many cells have a gap between two words of one line wider than SEG_NUM/SEG_DEN of their size: the
        // cell of a lattice with too few rules, whose columns are in the text.
        int c = cfirst;
        int n = 0;
        int k = 0;
        int wide = 0;
        while (c < cend) {
            wide = 0;
            k = 1;
            while ((k < emon.Port.CellsAt(tc, (c * Tcs) + 9)) && (wide == 0)) {
                int a = emon.Port.CellsAt(tw, emon.Port.CellsAt(tc, (c * Tcs) + 8) + (k - 1));
                int b = emon.Port.CellsAt(tw, emon.Port.CellsAt(tc, (c * Tcs) + 8) + k);
                int sz = TbMax(1, Evidence.WdGet(wd, b, Evidence.WfSize()));
                if (TbAbs(Evidence.WdGet(wd, a, Evidence.HdBy1()) - Evidence.WdGet(wd, b, Evidence.HdBy1())) <= (sz / 3)) {
                    if (((Evidence.WdGet(wd, b, Evidence.HdX0()) - Evidence.WdGet(wd, a, Evidence.HdX1())) * SegDen) > (sz * SegNum)) {
                        wide = 1;
                    }
                }
                k += 1;
            }
            n += wide;
            c += 1;
        }
        return n;
    }
    internal static int TbLattice(emon.Port.Cells rm, int root, emon.Port.Cells xs, emon.Port.Cells ys, int page, emon.Port.Cells gm, emon.Port.Cells tb, emon.Port.Cells tc, emon.Port.Cells wd, int w0, int w1, emon.Port.Cells pr, emon.Port.Cells so, emon.Port.Cells tw, emon.Port.Cells tx) {
        // The cells of one component's lattice, their words, and the candidate table. Answers its index, -1
        // when it is not a table.
        int nc = emon.Port.CellsLen(xs) - 1;
        int nr = emon.Port.CellsLen(ys) - 1;
        int cfirst = TbRowsOf(tc, Tcs);
        int tw0 = emon.Port.CellsLen(tw);
        int r = 0;
        int c = 0;
        int cs = 1;
        int rs = 1;
        int ok = 1;
        int cc = 0;
        if ((nc < 2) || (nr < 2)) {
            return -1;
        }
        if ((nc * nr) > 4000) {
            return -1;
        }
        emon.Port.CellsDrop(gm, 0);
        r = 0;
        while (r < (nc * nr)) {
            emon.Port.CellsPush(gm, -1);
            r += 1;
        }
        r = 0;
        while (r < nr) {
            c = 0;
            while (c < nc) {
                if (emon.Port.CellsAt(gm, (r * nc) + c) == -1) {
                    cs = 1;
                    ok = 1;
                    while ((ok == 1) && ((c + cs) < nc)) {
                        if ((emon.Port.CellsAt(gm, ((r * nc) + c) + cs) == -1) && !TbClosed(rm, root, 1, emon.Port.CellsAt(xs, c + cs), emon.Port.CellsAt(ys, r), emon.Port.CellsAt(ys, r + 1))) {
                            cs += 1;
                        } else {
                            ok = 0;
                        }
                    }
                    rs = 1;
                    ok = 1;
                    while ((ok == 1) && ((r + rs) < nr)) {
                        cc = c;
                        while ((ok == 1) && (cc < (c + cs))) {
                            if (emon.Port.CellsAt(gm, ((r + rs) * nc) + cc) == -1) {
                                if (TbClosed(rm, root, 0, emon.Port.CellsAt(ys, r + rs), emon.Port.CellsAt(xs, cc), emon.Port.CellsAt(xs, cc + 1))) {
                                    ok = 0;
                                }
                            } else {
                                ok = 0;
                            }
                            if ((ok == 1) && (cc > c)) {
                                if (TbClosed(rm, root, 1, emon.Port.CellsAt(xs, cc), emon.Port.CellsAt(ys, r + rs), emon.Port.CellsAt(ys, (r + rs) + 1))) {
                                    ok = 0;
                                }
                            }
                            cc += 1;
                        }
                        if (ok == 1) {
                            rs += 1;
                        }
                    }
                    int kc = TbCellAdd(tc, r, c, rs, cs, emon.Port.CellsAt(xs, c), emon.Port.CellsAt(ys, r), emon.Port.CellsAt(xs, c + cs), emon.Port.CellsAt(ys, r + rs));
                    int rr = r;
                    while (rr < (r + rs)) {
                        cc = c;
                        while (cc < (c + cs)) {
                            emon.Port.CellsSet(gm, (rr * nc) + cc, kc);
                            cc += 1;
                        }
                        rr += 1;
                    }
                }
                c += 1;
            }
            r += 1;
        }
        emon.Port.CellsDrop(pr, 0);
        int w = w0;
        while (w < w1) {
            int cx = (Evidence.WdGet(wd, w, Evidence.HdX0()) + Evidence.WdGet(wd, w, Evidence.HdX1())) / 2;
            int cy = (Evidence.WdGet(wd, w, Evidence.HdY0()) + Evidence.WdGet(wd, w, Evidence.HdY1())) / 2;
            int ci = TbIndexOf(xs, cx);
            int ri = TbIndexOf(ys, cy);
            if ((ci >= 0) && (ri >= 0)) {
                if (Evidence.WdGet(wd, w, Evidence.HdTlen()) > 0) {
                    TbPairAdd(pr, wd, emon.Port.CellsAt(gm, (ri * nc) + ci), w);
                }
            }
            w += 1;
        }
        TbFlushPairs(pr, so, wd, tc, tw);
        int total = TbRowsOf(tc, Tcs) - cfirst;
        int filled = 0;
        int k = cfirst;
        while (k < TbRowsOf(tc, Tcs)) {
            if (emon.Port.CellsAt(tc, (k * Tcs) + 9) > 0) {
                filled += 1;
            }
            k += 1;
        }
        if ((filled < 4) || ((filled * 5) < (total * 2))) {
            emon.Port.CellsDrop(tc, cfirst * Tcs);
            emon.Port.CellsDrop(tw, tw0);
            return -1;
        }
        if ((TbWideCells(tc, cfirst, cfirst + total, wd, tw) * 10) >= (filled * 3)) {
            emon.Port.CellsDrop(tc, cfirst * Tcs);
            emon.Port.CellsDrop(tw, tw0);
            return -1;
        }
        int t = TbAdd(tb, page, emon.Port.CellsAt(xs, 0), emon.Port.CellsAt(ys, 0), emon.Port.CellsAt(xs, nc), emon.Port.CellsAt(ys, nr), PfRuled, 900, nr, nc, cfirst, total);
        int i = 0;
        emon.Port.CellsSet(tb, (t * Tbs) + 16, emon.Port.CellsLen(tx));
        emon.Port.CellsSet(tb, (t * Tbs) + 17, nc + 1);
        while (i <= nc) {
            emon.Port.CellsPush(tx, emon.Port.CellsAt(xs, i));
            i += 1;
        }
        return t;
    }
    internal static int TbRuledPage(emon.Port.Cells rm, int page, emon.Port.Cells xs, emon.Port.Cells ys, emon.Port.Cells gm, emon.Port.Cells tb, emon.Port.Cells tc, emon.Port.Cells wd, int w0, int w1, emon.Port.Cells pr, emon.Port.Cells so, emon.Port.Cells tw, emon.Port.Cells tx) {
        // Every component of the page's merged rules with two rules each way is a lattice candidate.
        int n = TbRowsOf(rm, Rls);
        int i = 0;
        int j = 0;
        int nh = 0;
        int nv = 0;
        TbComponents(rm);
        while (i < n) {
            if (TbFind(rm, i) == i) {
                emon.Port.CellsDrop(xs, 0);
                emon.Port.CellsDrop(ys, 0);
                nh = 0;
                nv = 0;
                j = 0;
                while (j < n) {
                    if (TbFind(rm, j) == i) {
                        int pos = emon.Port.CellsAt(rm, (j * Rls) + 1);
                        int a0 = emon.Port.CellsAt(rm, (j * Rls) + 2);
                        int a1 = emon.Port.CellsAt(rm, (j * Rls) + 3);
                        if (emon.Port.CellsAt(rm, j * Rls) == 0) {
                            nh += 1;
                            emon.Port.CellsPush(ys, pos);
                            emon.Port.CellsPush(xs, a0);
                            emon.Port.CellsPush(xs, a1);
                        } else {
                            nv += 1;
                            emon.Port.CellsPush(xs, pos);
                            emon.Port.CellsPush(ys, a0);
                            emon.Port.CellsPush(ys, a1);
                        }
                    }
                    j += 1;
                }
                if ((nh >= 2) && (nv >= 2)) {
                    TbCluster(xs, 2 * PosTol);
                    TbCluster(ys, 2 * PosTol);
                    TbLattice(rm, i, xs, ys, page, gm, tb, tc, wd, w0, w1, pr, so, tw, tx);
                }
            }
            i += 1;
        }
        return 0;
    }
    internal static bool TbOverlap(emon.Port.Cells tb, int a, int b) {
        // Do the boxes of candidates a and b overlap by more than a rule's width both ways.
        int ax0 = emon.Port.CellsAt(tb, (a * Tbs) + 1);
        int ay0 = emon.Port.CellsAt(tb, (a * Tbs) + 2);
        int ax1 = emon.Port.CellsAt(tb, (a * Tbs) + 3);
        int ay1 = emon.Port.CellsAt(tb, (a * Tbs) + 4);
        int bx0 = emon.Port.CellsAt(tb, (b * Tbs) + 1);
        int by0 = emon.Port.CellsAt(tb, (b * Tbs) + 2);
        int bx1 = emon.Port.CellsAt(tb, (b * Tbs) + 3);
        int by1 = emon.Port.CellsAt(tb, (b * Tbs) + 4);
        return ((TbMin(ax1, bx1) - TbMax(ax0, bx0)) > PosTol) && ((TbMin(ay1, by1) - TbMax(ay0, by0)) > PosTol);
    }
    internal static int TbSelect(emon.Port.Cells tb, int t0, emon.Port.Cells so, emon.Port.Cells vals, emon.Port.Cells sa) {
        // Of the candidates t0.. of one page keep, best score first, those that overlap no better one, and
        // leave them in tb in the order of their tops. Answers how many are kept.
        int n = TbRowsOf(tb, Tbs);
        int i = t0;
        int j = 0;
        int kept = 0;
        int hit = 0;
        emon.Port.CellsDrop(so, 0);
        emon.Port.CellsDrop(vals, 0);
        while (i < n) {
            emon.Port.CellsPush(so, i - t0);
            emon.Port.CellsPush(vals, 0 - emon.Port.CellsAt(tb, (i * Tbs) + 6));
            emon.Port.CellsPush(vals, i);
            i += 1;
        }
        TbSortIdx(so, vals, 2, 0, 1);
        i = 0;
        while (i < emon.Port.CellsLen(so)) {
            int c = t0 + emon.Port.CellsAt(so, i);
            hit = 0;
            j = 0;
            while (j < i) {
                int o = t0 + emon.Port.CellsAt(so, j);
                if (emon.Port.CellsAt(tb, (o * Tbs) + 13) == 1) {
                    if (TbOverlap(tb, c, o)) {
                        hit = 1;
                    }
                }
                j += 1;
            }
            if (hit == 0) {
                emon.Port.CellsSet(tb, (c * Tbs) + 13, 1);
                kept += 1;
            } else {
                emon.Port.CellsSet(tb, (c * Tbs) + 13, 2);
            }
            i += 1;
        }
        emon.Port.CellsDrop(so, 0);
        emon.Port.CellsDrop(vals, 0);
        i = t0;
        while (i < n) {
            if (emon.Port.CellsAt(tb, (i * Tbs) + 13) == 1) {
                emon.Port.CellsPush(so, emon.Port.CellsLen(vals) / 2);
                emon.Port.CellsPush(vals, emon.Port.CellsAt(tb, (i * Tbs) + 2));
                emon.Port.CellsPush(vals, i);
            }
            i += 1;
        }
        TbSortIdx(so, vals, 2, 0, 1);
        emon.Port.CellsDrop(sa, 0);
        i = 0;
        while (i < emon.Port.CellsLen(so)) {
            int src = emon.Port.CellsAt(vals, (emon.Port.CellsAt(so, i) * 2) + 1);
            int f = 0;
            while (f < Tbs) {
                emon.Port.CellsPush(sa, emon.Port.CellsAt(tb, (src * Tbs) + f));
                f += 1;
            }
            i += 1;
        }
        emon.Port.CellsDrop(tb, t0 * Tbs);
        i = 0;
        while (i < emon.Port.CellsLen(sa)) {
            emon.Port.CellsPush(tb, emon.Port.CellsAt(sa, i));
            i += 1;
        }
        return kept;
    }
    internal static int TbClaim(emon.Port.Cells tb, int t0, emon.Port.Cells ln, int l0, int l1) {
        // Mark the lines of l0..l1 whose centre is in a kept table (t0.. of tb) with the table's index + 1.
        int n = TbRowsOf(tb, Tbs);
        int k = t0;
        int l = 0;
        while (k < n) {
            l = l0;
            while (l < l1) {
                int cx = (Evidence.LnGet(ln, l, Evidence.LhX0()) + Evidence.LnGet(ln, l, Evidence.LhX1())) / 2;
                int cy = (Evidence.LnGet(ln, l, Evidence.LhY0()) + Evidence.LnGet(ln, l, Evidence.LhY1())) / 2;
                if ((cx >= emon.Port.CellsAt(tb, (k * Tbs) + 1)) && (cx <= emon.Port.CellsAt(tb, (k * Tbs) + 3))) {
                    if ((cy >= emon.Port.CellsAt(tb, (k * Tbs) + 2)) && (cy <= emon.Port.CellsAt(tb, (k * Tbs) + 4))) {
                        if (Evidence.LnGet(ln, l, 15) == 0) {
                            Evidence.LnSet(ln, l, 15, TbHeld + k);
                        }
                    }
                }
                l += 1;
            }
            k += 1;
        }
        return 0;
    }
    internal static int TbPutProfile(emon.Port.Cells text, int prof) {
        // The profile's name (SPEC 10.5) appended to the text arena.
        if (prof == PfRuled) {
            Model.TextAppendCp(text, 114);
            Model.TextAppendCp(text, 117);
            Model.TextAppendCp(text, 108);
            Model.TextAppendCp(text, 101);
            Model.TextAppendCp(text, 100);
        }
        if (prof == PfPartial) {
            Model.TextAppendCp(text, 112);
            Model.TextAppendCp(text, 97);
            Model.TextAppendCp(text, 114);
            Model.TextAppendCp(text, 116);
            Model.TextAppendCp(text, 105);
            Model.TextAppendCp(text, 97);
            Model.TextAppendCp(text, 108);
        }
        if (prof == PfShaded) {
            Model.TextAppendCp(text, 115);
            Model.TextAppendCp(text, 104);
            Model.TextAppendCp(text, 97);
            Model.TextAppendCp(text, 100);
            Model.TextAppendCp(text, 101);
            Model.TextAppendCp(text, 100);
        }
        if (prof == PfWhitespace) {
            Model.TextAppendCp(text, 119);
            Model.TextAppendCp(text, 104);
            Model.TextAppendCp(text, 105);
            Model.TextAppendCp(text, 116);
            Model.TextAppendCp(text, 101);
            Model.TextAppendCp(text, 115);
            Model.TextAppendCp(text, 112);
            Model.TextAppendCp(text, 97);
            Model.TextAppendCp(text, 99);
            Model.TextAppendCp(text, 101);
        }
        return 0;
    }
    internal static int TbWordsRaw(emon.Port.Cells wd, emon.Port.Cells et, emon.Port.Cells tw, int from, int num, emon.Port.Cells raw) {
        // The words tw[first..first+count) as code points into `raw`: a space between two words, none after a
        // soft hyphen (which goes). `raw` is emptied first.
        int k = 0;
        int j = 0;
        int started = 0;
        emon.Port.CellsDrop(raw, 0);
        while (k < num) {
            int w = emon.Port.CellsAt(tw, from + k);
            int ts = Evidence.WdGet(wd, w, Evidence.HdTstart());
            int tl = Evidence.WdGet(wd, w, Evidence.HdTlen());
            if ((ts >= 0) && (tl > 0)) {
                if (started == 1) {
                    int n = emon.Port.CellsLen(raw);
                    if ((n > 0) && (emon.Port.CellsAt(raw, n - 1) == 173)) {
                        emon.Port.CellsDrop(raw, n - 1);
                    } else {
                        emon.Port.CellsPush(raw, 32);
                    }
                }
                started = 1;
                j = 0;
                while (j < tl) {
                    emon.Port.CellsPush(raw, emon.Port.CellsAt(et, ts + j));
                    j += 1;
                }
            }
            k += 1;
        }
        return 0;
    }
    internal static int TbEmitCell(emon.Port.Cells tb, int k, int c, int row, emon.Port.Cells wd, emon.Port.Cells et, emon.Port.Cells tc, emon.Port.Cells tw, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells text, emon.Port.Cells raw, emon.Port.Cells tmp) {
        int cb = c * Tcs;
        int page = emon.Port.CellsAt(tb, k * Tbs);
        int n = Model.NodeNew(nodes, Model.NkCell(), row);
        int wc = emon.Port.CellsAt(tc, cb + 9);
        Model.NodeSetConf(nodes, n, 600);
        Model.NodeAddSrc(nodes, n, Model.SrText());
        Model.NodeAddSrc(nodes, n, Model.SrInfer());
        if (emon.Port.CellsAt(tc, cb + 10) > 0) {
            Model.NodeSetSub(nodes, n, emon.Port.CellsAt(tc, cb + 10));
        }
        if (emon.Port.CellsAt(tc, cb + 2) > 1) {
            Model.NodeSetAttrInt(nodes, attrs, n, Model.FkRowspan(), emon.Port.CellsAt(tc, cb + 2));
        }
        if (emon.Port.CellsAt(tc, cb + 3) > 1) {
            Model.NodeSetAttrInt(nodes, attrs, n, Model.FkColspan(), emon.Port.CellsAt(tc, cb + 3));
        }
        if (emon.Port.CellsAt(tc, cb + 11) > 0) {
            Model.NodeSetAlign(nodes, attrs, n, emon.Port.CellsAt(tc, cb + 11));
        }
        Model.NodeAddRegion(nodes, regions, n, page, emon.Port.CellsAt(tc, cb + 4), emon.Port.CellsAt(tc, cb + 5), emon.Port.CellsAt(tc, cb + 6), emon.Port.CellsAt(tc, cb + 7));
        if (wc == 0) {
            Model.NodeSetAux(nodes, n, 1);
        } else {
            TbWordsRaw(wd, et, tw, emon.Port.CellsAt(tc, cb + 8), wc, raw);
            int t0 = emon.Port.CellsLen(text);
            Normalize.NzNfc(raw, 0, emon.Port.CellsLen(raw), text, tmp, Normalize.NzFlagLigatures() + Normalize.NzFlagRadicals());
            Model.NodeSetText(nodes, n, t0, emon.Port.CellsLen(text) - t0);
        }
        return 0;
    }
    internal static int TbPutWord(emon.Port.Cells text, emon.Port.Cells wd, emon.Port.Cells et, int w) {
        // The word's code points appended to the text arena without its trailing full stops and colons.
        int ts = Evidence.WdGet(wd, w, Evidence.HdTstart());
        int tl = Evidence.WdGet(wd, w, Evidence.HdTlen());
        int j = 0;
        while ((tl > 1) && ((emon.Port.CellsAt(et, ts + (tl - 1)) == 46) || (emon.Port.CellsAt(et, ts + (tl - 1)) == 58))) {
            tl -= 1;
        }
        while (j < tl) {
            Model.TextAppendCp(text, emon.Port.CellsAt(et, ts + j));
            j += 1;
        }
        return 0;
    }
    internal static bool TbSeparator(emon.Port.Cells wd, emon.Port.Cells et, int w) {
        // A word that is only a separator between a label and its text: . : - en dash em dash.
        int ts = Evidence.WdGet(wd, w, Evidence.HdTstart());
        int tl = Evidence.WdGet(wd, w, Evidence.HdTlen());
        if (tl != 1) {
            return 0 == 1;
        }
        int cp = emon.Port.CellsAt(et, ts);
        return (cp == 46) || ((cp == 58) || ((cp == 45) || ((cp == 8211) || (cp == 8212))));
    }
    internal static int TbEmitCaption(emon.Port.Cells tb, int k, emon.Port.Cells wd, emon.Port.Cells et, emon.Port.Cells ln, emon.Port.Cells tq, int t, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells text, emon.Port.Cells raw, emon.Port.Cells tmp) {
        // The caption of table k as the table's first child: `label` (the keyword and the number), the rest as its text.
        int b = k * Tbs;
        int qn = emon.Port.CellsAt(tb, b + 15);
        int qf = emon.Port.CellsAt(tb, b + 14);
        if (qn == 0) {
            return 0;
        }
        int capn = Model.NodeNew(nodes, Model.NkCaption(), t);
        int l0 = emon.Port.CellsAt(tq, qf);
        int w0 = Evidence.LnGet(ln, l0, Evidence.LhFirst());
        int s = emon.Port.CellsLen(text);
        int x0 = 2000000000;
        int y0 = 2000000000;
        int x1 = -2000000000;
        int y1 = -2000000000;
        int q = 0;
        int gi = 0;
        int j = 0;
        int started = 0;
        Model.NodeSetConf(nodes, capn, 600);
        Model.NodeAddSrc(nodes, capn, Model.SrText());
        Model.NodeAddSrc(nodes, capn, Model.SrInfer());
        TbPutWord(text, wd, et, w0);
        Model.TextAppendCp(text, 32);
        TbPutWord(text, wd, et, w0 + 1);
        Model.NodeSetAttrText(nodes, attrs, capn, Model.FkLabel(), s, emon.Port.CellsLen(text) - s);
        emon.Port.CellsDrop(raw, 0);
        while (q < qn) {
            int l = emon.Port.CellsAt(tq, qf + q);
            int lf = Evidence.LnGet(ln, l, Evidence.LhFirst());
            int lc = Evidence.LnGet(ln, l, Evidence.LhCount());
            if (Evidence.LnGet(ln, l, Evidence.LhX0()) < x0) {
                x0 = Evidence.LnGet(ln, l, Evidence.LhX0());
            }
            if (Evidence.LnGet(ln, l, Evidence.LhY0()) < y0) {
                y0 = Evidence.LnGet(ln, l, Evidence.LhY0());
            }
            if (Evidence.LnGet(ln, l, Evidence.LhX1()) > x1) {
                x1 = Evidence.LnGet(ln, l, Evidence.LhX1());
            }
            if (Evidence.LnGet(ln, l, Evidence.LhY1()) > y1) {
                y1 = Evidence.LnGet(ln, l, Evidence.LhY1());
            }
            j = 0;
            while (j < lc) {
                int w = lf + j;
                int ts = Evidence.WdGet(wd, w, Evidence.HdTstart());
                int tl = Evidence.WdGet(wd, w, Evidence.HdTlen());
                if ((gi >= 2) && (tl > 0)) {
                    if (!((started == 0) && TbSeparator(wd, et, w))) {
                        if (started == 1) {
                            emon.Port.CellsPush(raw, 32);
                        }
                        started = 1;
                        int m = 0;
                        while (m < tl) {
                            emon.Port.CellsPush(raw, emon.Port.CellsAt(et, ts + m));
                            m += 1;
                        }
                    }
                }
                gi += 1;
                j += 1;
            }
            q += 1;
        }
        int t0 = emon.Port.CellsLen(text);
        Normalize.NzNfc(raw, 0, emon.Port.CellsLen(raw), text, tmp, Normalize.NzFlagLigatures() + Normalize.NzFlagRadicals());
        Model.NodeSetText(nodes, capn, t0, emon.Port.CellsLen(text) - t0);
        Model.NodeAddRegion(nodes, regions, capn, emon.Port.CellsAt(tb, b), x0, y0, x1, y1);
        return capn;
    }
    public static int TbCount(emon.Port.Cells tb) {
        return TbRowsOf(tb, Tbs);
    }
    public static int TbPage(emon.Port.Cells tb, int k) {
        return emon.Port.CellsAt(tb, k * Tbs);
    }
    public static int TbTop(emon.Port.Cells tb, int k) {
        return emon.Port.CellsAt(tb, (k * Tbs) + 2);
    }
    public static bool TbDue(emon.Port.Cells tb, int k, int page, int ymid2) {
        // Is table k on this page, and its top at or above twice-the-y `ymid2` (a line's baseline sum).
        if (k >= TbRowsOf(tb, Tbs)) {
            return 0 == 1;
        }
        if (emon.Port.CellsAt(tb, k * Tbs) != page) {
            return 0 == 1;
        }
        return (2 * emon.Port.CellsAt(tb, (k * Tbs) + 2)) <= ymid2;
    }
    public static int TbSkip(emon.Port.Cells tb, int k, int page) {
        // The first table at or after k that is on a page at or after `page`.
        int i = k;
        while ((i < TbRowsOf(tb, Tbs)) && (emon.Port.CellsAt(tb, i * Tbs) < page)) {
            i += 1;
        }
        return i;
    }
    internal static int TbEmitDropped(emon.Port.Cells tb, int f, int r, emon.Port.Cells wd, emon.Port.Cells et, emon.Port.Cells tc, emon.Port.Cells tw, emon.Port.Cells text, emon.Port.Cells raw, emon.Port.Cells tmp, emon.Port.Cells ledger) {
        // A header row of fragment f that repeats the first fragment's (P5.4): into the ledger as `duplicate-header-row`,
        // its box, and its cells' text joined by a space.
        int b = f * Tbs;
        int cfirst = emon.Port.CellsAt(tb, b + 9);
        int cend = cfirst + emon.Port.CellsAt(tb, b + 10);
        int c = cfirst;
        int x0 = 2000000000;
        int y0 = 2000000000;
        int x1 = -2000000000;
        int y1 = -2000000000;
        int any = 0;
        int s = emon.Port.CellsLen(text);
        while (c < cend) {
            if (emon.Port.CellsAt(tc, c * Tcs) == r) {
                if (emon.Port.CellsAt(tc, (c * Tcs) + 4) < x0) {
                    x0 = emon.Port.CellsAt(tc, (c * Tcs) + 4);
                }
                if (emon.Port.CellsAt(tc, (c * Tcs) + 5) < y0) {
                    y0 = emon.Port.CellsAt(tc, (c * Tcs) + 5);
                }
                if (emon.Port.CellsAt(tc, (c * Tcs) + 6) > x1) {
                    x1 = emon.Port.CellsAt(tc, (c * Tcs) + 6);
                }
                if (emon.Port.CellsAt(tc, (c * Tcs) + 7) > y1) {
                    y1 = emon.Port.CellsAt(tc, (c * Tcs) + 7);
                }
                if (emon.Port.CellsAt(tc, (c * Tcs) + 9) > 0) {
                    if (any == 1) {
                        Model.TextAppendCp(text, 32);
                    }
                    any = 1;
                    TbWordsRaw(wd, et, tw, emon.Port.CellsAt(tc, (c * Tcs) + 8), emon.Port.CellsAt(tc, (c * Tcs) + 9), raw);
                    Normalize.NzNfc(raw, 0, emon.Port.CellsLen(raw), text, tmp, Normalize.NzFlagLigatures() + Normalize.NzFlagRadicals());
                }
            }
            c += 1;
        }
        int l = Model.LedgerAdd(ledger, Model.DrDuplicateHeaderRow(), emon.Port.CellsAt(tb, b), x0, y0, x1, y1, 700, Model.SrText() + Model.SrInfer());
        Model.LedgerSetText(ledger, l, s, emon.Port.CellsLen(text) - s);
        return 0;
    }
    public static int TbEmit(emon.Port.Cells tb, int k, int parent, emon.Port.Cells wd, emon.Port.Cells et, emon.Port.Cells ln, emon.Port.Cells tc, emon.Port.Cells tw, emon.Port.Cells tq, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells text, emon.Port.Cells raw, emon.Port.Cells tmp, emon.Port.Cells ledger) {
        // Append table k to the Model under `parent` (the root, or the open section, D178): the table node, its caption, its row groups, rows
        // and cells, in document order; the fragments that follow it on later pages (`tb-link`) are its rows too, and
        // their repeated header rows go to the ledger. A table that is a later fragment of another is not written
        // (answers -1). Answers the table's node.
        if (emon.Port.CellsAt(tb, (k * Tbs) + 21) != 0) {
            return -1;
        }
        int b = k * Tbs;
        int prof = emon.Port.CellsAt(tb, b + 5);
        int nhead = emon.Port.CellsAt(tb, b + 11);
        int t = Model.NodeNew(nodes, Model.NkTable(), parent);
        int f = k;
        int g = -1;
        int role = 0;
        int row = -1;
        int r = 0;
        int ci = 0;
        int want = 0;
        Model.NodeSetConf(nodes, t, 600);
        Model.NodeAddSrc(nodes, t, Model.SrText());
        Model.NodeAddSrc(nodes, t, Model.SrInfer());
        if (prof == PfRuled) {
            Model.NodeAddSrc(nodes, t, Model.SrVector());
        }
        int s = emon.Port.CellsLen(text);
        TbPutProfile(text, prof);
        Model.NodeSetAttrText(nodes, attrs, t, Model.FkProfile(), s, emon.Port.CellsLen(text) - s);
        Model.NodeSetAttrInt(nodes, attrs, t, Model.FkColumns(), emon.Port.CellsAt(tb, b + 8));
        if (emon.Port.CellsAt(tb, b + 18) > 1) {
            Model.NodeSetAttrInt(nodes, attrs, t, Model.FkContinued(), emon.Port.CellsAt(tb, b + 18));
        }
        TbEmitCaption(tb, k, wd, et, ln, tq, t, nodes, attrs, regions, text, raw, tmp);
        while (f >= 0) {
            int fb = f * Tbs;
            int nrows = emon.Port.CellsAt(tb, fb + 7);
            int cfirst = emon.Port.CellsAt(tb, fb + 9);
            int cend = cfirst + emon.Port.CellsAt(tb, fb + 10);
            int nfoot = emon.Port.CellsAt(tb, fb + 12);
            int nxt = emon.Port.CellsAt(tb, fb + 19);
            int skip = emon.Port.CellsAt(tb, fb + 20);
            Model.NodeAddRegion(nodes, regions, t, emon.Port.CellsAt(tb, fb), emon.Port.CellsAt(tb, fb + 1), emon.Port.CellsAt(tb, fb + 2), emon.Port.CellsAt(tb, fb + 3), emon.Port.CellsAt(tb, fb + 4));
            r = 0;
            while (r < skip) {
                TbEmitDropped(tb, f, r, wd, et, tc, tw, text, raw, tmp, ledger);
                r += 1;
            }
            ci = cfirst;
            while ((ci < cend) && (emon.Port.CellsAt(tc, ci * Tcs) < skip)) {
                ci += 1;
            }
            while (r < nrows) {
                want = Model.RlBody();
                if ((f == k) && (r < nhead)) {
                    want = Model.RlHead();
                }
                if ((nxt == 0) && (r >= (nrows - nfoot))) {
                    want = Model.RlFoot();
                }
                if (want != role) {
                    g = Model.NodeNew(nodes, Model.NkRowgroup(), t);
                    Model.NodeSetSub(nodes, g, want);
                    Model.NodeSetConf(nodes, g, 600);
                    Model.NodeAddSrc(nodes, g, Model.SrInfer());
                    role = want;
                }
                row = Model.NodeNew(nodes, Model.NkRow(), g);
                Model.NodeSetConf(nodes, row, 600);
                Model.NodeAddSrc(nodes, row, Model.SrInfer());
                while ((ci < cend) && (emon.Port.CellsAt(tc, ci * Tcs) == r)) {
                    if ((emon.Port.CellsAt(tc, (ci * Tcs) + 12) & 1) == 0) {
                        TbEmitCell(tb, f, ci, row, wd, et, tc, tw, nodes, attrs, regions, text, raw, tmp);
                    }
                    ci += 1;
                }
                r += 1;
            }
            f = nxt - 1;
        }
        return t;
    }
    internal static bool TbUpright(emon.Port.Cells wd, int w) {
        int r = Evidence.WdGet(wd, w, Evidence.HdRot());
        return (r < 100) || (r > 35900);
    }
    internal static bool TbWless(emon.Port.Cells wd, int a, int b, int mode) {
        // Does word a come before word b: mode 0 by baseline then x, mode 1 by x; then by index.
        if (mode == 0) {
            int ya = Evidence.WdGet(wd, a, Evidence.HdBy1());
            int yb = Evidence.WdGet(wd, b, Evidence.HdBy1());
            if (ya != yb) {
                return ya < yb;
            }
        }
        int xa = Evidence.WdGet(wd, a, Evidence.HdX0());
        int xb = Evidence.WdGet(wd, b, Evidence.HdX0());
        if (xa != xb) {
            return xa < xb;
        }
        return a < b;
    }
    internal static int TbSortWords(emon.Port.Cells wl, emon.Port.Cells wd, int from, int to, int mode) {
        // Shell sort of wl[from, to) by `tb-wless`.
        int n = to - from;
        int h = 1;
        int i = 0;
        int j = 0;
        int v = 0;
        int u = 0;
        int more = 1;
        while (h < (n / 3)) {
            h = (h * 3) + 1;
        }
        while (h >= 1) {
            i = h;
            while (i < n) {
                v = emon.Port.CellsAt(wl, from + i);
                j = i;
                more = 1;
                while ((j >= h) && (more == 1)) {
                    u = emon.Port.CellsAt(wl, from + (j - h));
                    if (TbWless(wd, v, u, mode)) {
                        emon.Port.CellsSet(wl, from + j, u);
                        j -= h;
                    } else {
                        more = 0;
                    }
                }
                emon.Port.CellsSet(wl, from + j, v);
                i += 1;
            }
            h = (h - 1) / 3;
        }
        return 0;
    }
    internal static int TbRows(emon.Port.Cells wd, int w0, int w1, int rx0, int ry0, int rx1, int ry1, emon.Port.Cells wl, emon.Port.Cells rw, emon.Port.Cells sg) {
        // The upright words w0..w1 of the page whose centre is in the box, as baseline rows and chunks (see the
        // head of this section). Answers the number of rows.
        int w = w0;
        int i = 0;
        int j = 0;
        int n = 0;
        emon.Port.CellsDrop(wl, 0);
        emon.Port.CellsDrop(rw, 0);
        emon.Port.CellsDrop(sg, 0);
        while (w < w1) {
            int cx = (Evidence.WdGet(wd, w, Evidence.HdX0()) + Evidence.WdGet(wd, w, Evidence.HdX1())) / 2;
            int cy = (Evidence.WdGet(wd, w, Evidence.HdY0()) + Evidence.WdGet(wd, w, Evidence.HdY1())) / 2;
            if ((Evidence.WdGet(wd, w, Evidence.HdTlen()) > 0) && TbUpright(wd, w)) {
                if ((cx >= rx0) && ((cx <= rx1) && ((cy >= ry0) && (cy <= ry1)))) {
                    emon.Port.CellsPush(wl, w);
                }
            }
            w += 1;
        }
        n = emon.Port.CellsLen(wl);
        TbSortWords(wl, wd, 0, n, 0);
        i = 0;
        while (i < n) {
            int w0i = emon.Port.CellsAt(wl, i);
            int tol = (3 * TbMax(500, Evidence.WdGet(wd, w0i, Evidence.WfSize()))) / 10;
            // A row is a CHAIN of baselines: each word within a third of the size of the one before it in baseline
            // order (not of the first: a scan's rows slope, so one row's baselines spread over several points: OCR lines in the table stage, D213).
            j = i + 1;
            while ((j < n) && (TbAbs(Evidence.WdGet(wd, emon.Port.CellsAt(wl, j), Evidence.HdBy1()) - Evidence.WdGet(wd, emon.Port.CellsAt(wl, j - 1), Evidence.HdBy1())) <= tol)) {
                j += 1;
            }
            TbSortWords(wl, wd, i, j, 1);
            int ri = TbRowsOf(rw, Rws);
            int sumy = 0;
            int sums = 0;
            int x0 = 2000000000;
            int x1 = -2000000000;
            int y0 = 2000000000;
            int y1 = -2000000000;
            int k = i;
            while (k < j) {
                int wk = emon.Port.CellsAt(wl, k);
                sumy += Evidence.WdGet(wd, wk, Evidence.HdBy1());
                sums += TbMax(1, Evidence.WdGet(wd, wk, Evidence.WfSize()));
                if (Evidence.WdGet(wd, wk, Evidence.HdX0()) < x0) {
                    x0 = Evidence.WdGet(wd, wk, Evidence.HdX0());
                }
                if (Evidence.WdGet(wd, wk, Evidence.HdX1()) > x1) {
                    x1 = Evidence.WdGet(wd, wk, Evidence.HdX1());
                }
                if (Evidence.WdGet(wd, wk, Evidence.HdY0()) < y0) {
                    y0 = Evidence.WdGet(wd, wk, Evidence.HdY0());
                }
                if (Evidence.WdGet(wd, wk, Evidence.HdY1()) > y1) {
                    y1 = Evidence.WdGet(wd, wk, Evidence.HdY1());
                }
                k += 1;
            }
            int cnt = j - i;
            int size = sums / cnt;
            int thr = (size * SegNum) / SegDen;
            int sf = TbRowsOf(sg, Sgs);
            int cstart = i;
            int cmax = Evidence.WdGet(wd, emon.Port.CellsAt(wl, i), Evidence.HdX1());
            emon.Port.CellsPush(rw, i);
            emon.Port.CellsPush(rw, cnt);
            emon.Port.CellsPush(rw, sumy / cnt);
            emon.Port.CellsPush(rw, size);
            emon.Port.CellsPush(rw, x0);
            emon.Port.CellsPush(rw, x1);
            emon.Port.CellsPush(rw, y0);
            emon.Port.CellsPush(rw, y1);
            emon.Port.CellsPush(rw, sf);
            emon.Port.CellsPush(rw, 0);
            k = i + 1;
            while (k <= j) {
                if ((k == j) || ((Evidence.WdGet(wd, emon.Port.CellsAt(wl, k), Evidence.HdX0()) - cmax) > thr)) {
                    emon.Port.CellsPush(sg, ri);
                    emon.Port.CellsPush(sg, Evidence.WdGet(wd, emon.Port.CellsAt(wl, cstart), Evidence.HdX0()));
                    emon.Port.CellsPush(sg, cmax);
                    emon.Port.CellsPush(sg, cstart);
                    emon.Port.CellsPush(sg, k - cstart);
                    emon.Port.CellsPush(sg, 0);
                    if (k < j) {
                        cstart = k;
                        cmax = Evidence.WdGet(wd, emon.Port.CellsAt(wl, k), Evidence.HdX1());
                    }
                }
                if (k < j) {
                    if (Evidence.WdGet(wd, emon.Port.CellsAt(wl, k), Evidence.HdX1()) > cmax) {
                        cmax = Evidence.WdGet(wd, emon.Port.CellsAt(wl, k), Evidence.HdX1());
                    }
                }
                k += 1;
            }
            emon.Port.CellsSet(rw, (ri * Rws) + 9, TbRowsOf(sg, Sgs) - sf);
            i = j;
        }
        return TbRowsOf(rw, Rws);
    }
    internal static int TbChannels(emon.Port.Cells wd, emon.Port.Cells wl, emon.Port.Cells rw, emon.Port.Cells sg, int ra, int rb, int allow, int minw, emon.Port.Cells ch, emon.Port.Cells st, emon.Port.Cells en) {
        // The channels of rows ra..rb: the stretches of the x axis, at least minw wide, that at most `allow` of the
        // tabular rows' words (rows of two chunks or more) cover. `st` and `en` are scratch. Answers how many.
        int r = ra;
        int k = 0;
        int i = 0;
        int j = 0;
        int cov = 0;
        int prev = 0;
        int cs = -1;
        int ce = 0;
        emon.Port.CellsDrop(ch, 0);
        emon.Port.CellsDrop(st, 0);
        emon.Port.CellsDrop(en, 0);
        while (r < rb) {
            if (emon.Port.CellsAt(rw, (r * Rws) + 9) >= 2) {
                k = 0;
                while (k < emon.Port.CellsAt(rw, (r * Rws) + 1)) {
                    int w = emon.Port.CellsAt(wl, emon.Port.CellsAt(rw, r * Rws) + k);
                    emon.Port.CellsPush(st, Evidence.WdGet(wd, w, Evidence.HdX0()));
                    emon.Port.CellsPush(en, Evidence.WdGet(wd, w, Evidence.HdX1()));
                    k += 1;
                }
            }
            r += 1;
        }
        TbSortNums(st);
        TbSortNums(en);
        int n = emon.Port.CellsLen(st);
        if (n == 0) {
            return 0;
        }
        prev = emon.Port.CellsAt(st, 0);
        while ((i < n) || (j < n)) {
            int x = 0;
            if (i < n) {
                x = emon.Port.CellsAt(st, i);
            } else {
                x = emon.Port.CellsAt(en, j);
            }
            if ((j < n) && (emon.Port.CellsAt(en, j) < x)) {
                x = emon.Port.CellsAt(en, j);
            }
            if (cov <= allow) {
                if (cs < 0) {
                    cs = prev;
                }
                ce = x;
            } else {
                if (cs >= 0) {
                    if ((ce - cs) >= minw) {
                        emon.Port.CellsPush(ch, cs);
                        emon.Port.CellsPush(ch, ce);
                    }
                    cs = -1;
                }
            }
            while ((i < n) && (emon.Port.CellsAt(st, i) == x)) {
                cov += 1;
                i += 1;
            }
            while ((j < n) && (emon.Port.CellsAt(en, j) == x)) {
                cov -= 1;
                j += 1;
            }
            prev = x;
        }
        if ((cs >= 0) && ((ce - cs) >= minw)) {
            emon.Port.CellsPush(ch, cs);
            emon.Port.CellsPush(ch, ce);
        }
        return emon.Port.CellsLen(ch) / 2;
    }
    internal static int TbColOf(emon.Port.Cells ch, int x) {
        // The column of x: how many channel midpoints are at or before it.
        int n = emon.Port.CellsLen(ch) / 2;
        int i = 0;
        int c = 0;
        while (i < n) {
            if (((emon.Port.CellsAt(ch, i * 2) + emon.Port.CellsAt(ch, (i * 2) + 1)) / 2) <= x) {
                c += 1;
            }
            i += 1;
        }
        return c;
    }
    internal static int TbWordCx(emon.Port.Cells wd, int w) {
        return (Evidence.WdGet(wd, w, Evidence.HdX0()) + Evidence.WdGet(wd, w, Evidence.HdX1())) / 2;
    }
    internal static int TbChunkA(emon.Port.Cells wd, emon.Port.Cells wl, emon.Port.Cells sg, emon.Port.Cells ch, int s) {
        // The first column of chunk s: the column of its first word's centre.
        return TbColOf(ch, TbWordCx(wd, emon.Port.CellsAt(wl, emon.Port.CellsAt(sg, (s * Sgs) + 3))));
    }
    internal static int TbChunkB(emon.Port.Cells wd, emon.Port.Cells wl, emon.Port.Cells sg, emon.Port.Cells ch, int s) {
        // The last column of chunk s: the column of its last word's centre.
        return TbColOf(ch, TbWordCx(wd, emon.Port.CellsAt(wl, (emon.Port.CellsAt(sg, (s * Sgs) + 3) + emon.Port.CellsAt(sg, (s * Sgs) + 4)) - 1)));
    }
    internal static int TbRowMap(emon.Port.Cells wd, emon.Port.Cells wl, emon.Port.Cells rw, emon.Port.Cells sg, emon.Port.Cells ch, int ra, int rb, int ncols, emon.Port.Cells rmap, emon.Port.Cells occ) {
        // The table row of each baseline row ra..rb (rmap[r - ra]): a baseline row goes on the row above when
        // it is a continuation of a wrapped cell: a tight line pitch (at most 1.35 of the size and 4/5 of the
        // mean pitch), no chunk with a span, and chunks only in columns the row above had, at most half of them.
        // Answers the number of table rows.
        int r = ra;
        int rows = -1;
        int c = 0;
        int cont = 0;
        int occn = 0;
        int ok = 1;
        int s = 0;
        int mean = 0;
        if ((rb - ra) > 1) {
            mean = (emon.Port.CellsAt(rw, ((rb - 1) * Rws) + 2) - emon.Port.CellsAt(rw, (ra * Rws) + 2)) / ((rb - ra) - 1);
        }
        emon.Port.CellsDrop(rmap, 0);
        emon.Port.CellsDrop(occ, 0);
        while (c < ncols) {
            emon.Port.CellsPush(occ, 0);
            c += 1;
        }
        while (r < rb) {
            cont = 0;
            if ((rows > -1) && (r > ra)) {
                int pitch = emon.Port.CellsAt(rw, (r * Rws) + 2) - emon.Port.CellsAt(rw, ((r - 1) * Rws) + 2);
                int size = emon.Port.CellsAt(rw, (r * Rws) + 3);
                int nchunks = emon.Port.CellsAt(rw, (r * Rws) + 9);
                if (((pitch * 20) <= (size * 27)) && ((mean > 0) && ((pitch * 5) <= (mean * 4)))) {
                    occn = 0;
                    c = 0;
                    while (c < ncols) {
                        if (emon.Port.CellsAt(occ, c) == 1) {
                            occn += 1;
                        }
                        c += 1;
                    }
                    if ((nchunks < occn) && ((nchunks * 2) <= occn)) {
                        ok = 1;
                        s = 0;
                        while (s < nchunks) {
                            int si = emon.Port.CellsAt(rw, (r * Rws) + 8) + s;
                            int a = TbChunkA(wd, wl, sg, ch, si);
                            int b = TbChunkB(wd, wl, sg, ch, si);
                            if (a != b) {
                                ok = 0;
                            }
                            if (emon.Port.CellsAt(occ, a) != 1) {
                                ok = 0;
                            }
                            s += 1;
                        }
                        cont = ok;
                    }
                }
            }
            if (cont == 0) {
                rows += 1;
                c = 0;
                while (c < ncols) {
                    emon.Port.CellsSet(occ, c, 0);
                    c += 1;
                }
            }
            s = 0;
            while (s < emon.Port.CellsAt(rw, (r * Rws) + 9)) {
                int si = emon.Port.CellsAt(rw, (r * Rws) + 8) + s;
                int a = TbChunkA(wd, wl, sg, ch, si);
                int b = TbChunkB(wd, wl, sg, ch, si);
                c = a;
                while (c <= b) {
                    emon.Port.CellsSet(occ, c, 1);
                    c += 1;
                }
                s += 1;
            }
            emon.Port.CellsPush(rmap, rows);
            r += 1;
        }
        return rows + 1;
    }
    internal static int TbCut(emon.Port.Cells ch, int k, int lo, int hi) {
        // The boundary before column k: lo for the first, else the midpoint of channel k-1; hi after the last.
        int n = emon.Port.CellsLen(ch) / 2;
        if (k <= 0) {
            return lo;
        }
        if (k > n) {
            return hi;
        }
        return (emon.Port.CellsAt(ch, (k - 1) * 2) + emon.Port.CellsAt(ch, ((k - 1) * 2) + 1)) / 2;
    }
    internal static int TbTextGrid(emon.Port.Cells wd, emon.Port.Cells wl, emon.Port.Cells rw, emon.Port.Cells sg, emon.Port.Cells ch, emon.Port.Cells st, emon.Port.Cells en, emon.Port.Cells rmap, emon.Port.Cells gm, emon.Port.Cells gs, emon.Port.Cells ry, emon.Port.Cells pr, emon.Port.Cells so, emon.Port.Cells tb, emon.Port.Cells tc, emon.Port.Cells tw, emon.Port.Cells tx, int page, int ra, int rb, int profile, int score, int ext, int bx0, int by0, int bx1, int by1) {
        // The cells of the rows ra..rb (see the head of this section) as a candidate table of this profile:
        // ext 1 means `rmap` already says which table row each baseline row is (shaded: the fills' bands). The box
        // bx0..by1 widens the box of the words (the rules, the fills): 2000000000 2000000000 -2000000000 -2000000000
        // for none. Answers the
        // table's index, -1 when there are not two columns and two rows.
        int ntab = 0;
        int sumsz = 0;
        int r = ra;
        int nch = 0;
        int ncols = 0;
        int nrows = 0;
        int c = 0;
        int s = 0;
        int q = 0;
        int a = 0;
        int b = 0;
        int tr = 0;
        int minx = 2000000000;
        int maxx = -2000000000;
        int miny = 2000000000;
        int maxy = -2000000000;
        while (r < rb) {
            if (emon.Port.CellsAt(rw, (r * Rws) + 9) >= 2) {
                ntab += 1;
            }
            sumsz += emon.Port.CellsAt(rw, (r * Rws) + 3);
            if (emon.Port.CellsAt(rw, (r * Rws) + 4) < minx) {
                minx = emon.Port.CellsAt(rw, (r * Rws) + 4);
            }
            if (emon.Port.CellsAt(rw, (r * Rws) + 5) > maxx) {
                maxx = emon.Port.CellsAt(rw, (r * Rws) + 5);
            }
            if (emon.Port.CellsAt(rw, (r * Rws) + 6) < miny) {
                miny = emon.Port.CellsAt(rw, (r * Rws) + 6);
            }
            if (emon.Port.CellsAt(rw, (r * Rws) + 7) > maxy) {
                maxy = emon.Port.CellsAt(rw, (r * Rws) + 7);
            }
            r += 1;
        }
        if ((ntab < 2) || ((rb - ra) <= 1)) {
            return -1;
        }
        nch = TbChannels(wd, wl, rw, sg, ra, rb, ntab / 6, ((sumsz / (rb - ra)) * SegNum) / SegDen, ch, st, en);
        if (nch < 1) {
            return -1;
        }
        ncols = nch + 1;
        if (ncols > 40) {
            return -1;
        }
