        emon.Port.CellsDrop(gs, 0);
        emon.Port.CellsDrop(en, 0);
        emon.Port.CellsDrop(ry, 0);
        c = 0;
        while (c < (nrows * ncols)) {
            emon.Port.CellsPush(gm, -1);
