            emon.Port.CellsPush(en, -1);
            c += 1;
        }
        c = 0;
        while (c < nrows) {
            emon.Port.CellsPush(ry, 2000000000);
            emon.Port.CellsPush(ry, -2000000000);
            c += 1;
        }
        r = ra;
        while (r < rb) {
            tr = emon.Port.CellsAt(rmap, r - ra);
            if (tr >= 0) {
                if (emon.Port.CellsAt(rw, (r * Rws) + 6) < emon.Port.CellsAt(ry, tr * 2)) {
                    emon.Port.CellsSet(ry, tr * 2, emon.Port.CellsAt(rw, (r * Rws) + 6));
                }
                if (emon.Port.CellsAt(rw, (r * Rws) + 7) > emon.Port.CellsAt(ry, (tr * 2) + 1)) {
                    emon.Port.CellsSet(ry, (tr * 2) + 1, emon.Port.CellsAt(rw, (r * Rws) + 7));
                }
                s = 0;
                while (s < emon.Port.CellsAt(rw, (r * Rws) + 9)) {
                    q = emon.Port.CellsAt(rw, (r * Rws) + 8) + s;
                    a = TbChunkA(wd, wl, sg, ch, q);
                    b = TbChunkB(wd, wl, sg, ch, q);
                    if (emon.Port.CellsAt(gm, (tr * ncols) + a) == -1) {
                        int free = 1;
                        int kf = a;
                        while (kf <= b) {
                            if (emon.Port.CellsAt(gm, (tr * ncols) + kf) != -1) {
                                free = 0;
                            }
                            kf += 1;
                        }
                        if (free == 0) {
