                    a = TbChunkA(wd, wl, sg, ch, q);
                    int cell = emon.Port.CellsAt(en, (tr * ncols) + a);
                    int kw = emon.Port.CellsAt(sg, (q * Sgs) + 3);
                    while (kw < (emon.Port.CellsAt(sg, (q * Sgs) + 3) + emon.Port.CellsAt(sg, (q * Sgs) + 4))) {
                        TbPairAdd(pr, wd, cell, emon.Port.CellsAt(wl, kw));
                        kw += 1;
                    }
                    s += 1;
                }
            }
            r += 1;
        }
        TbFlushPairs(pr, so, wd, tc, tw);
        int x0 = minx;
        int y0 = miny;
        int x1 = maxx;
        int y1 = maxy;
        if (bx0 < x0) {
            x0 = bx0;
        }
        if (by0 < y0) {
            y0 = by0;
        }
        if (bx1 > x1) {
            x1 = bx1;
        }
        if (by1 > y1) {
            y1 = by1;
        }
        int t = TbAdd(tb, page, x0, y0, x1, y1, profile, score, nrows, ncols, cfirst, TbRowsOf(tc, Tcs) - cfirst);
        int k = 0;
        emon.Port.CellsSet(tb, (t * Tbs) + 16, emon.Port.CellsLen(tx));
        emon.Port.CellsSet(tb, (t * Tbs) + 17, ncols + 1);
        while (k <= ncols) {
            emon.Port.CellsPush(tx, TbCut(ch, k, minx, maxx));
            k += 1;
        }
