    internal static bool TbNumChar(int cp) {
        // A character a number may hold besides digits: separators, signs, currency, percent, brackets.
        return (cp == 44) || ((cp == 46) || ((cp == 45) || ((cp == 43) || ((cp == 37) || ((cp == 36) || ((cp == 8364) || ((cp == 163) || ((cp == 165) || ((cp == 40) || ((cp == 41) || ((cp == 47) || ((cp == 58) || ((cp == 8722) || ((cp == 8211) || ((cp == 160) || ((cp == 8201) || (cp == 8239)))))))))))))))));
    }
    internal static int TbCellNumeric(emon.Port.Cells wd, emon.Port.Cells et, emon.Port.Cells tw, emon.Port.Cells tc, int c) {
        // 1 when the cell is up to three words made only of digits and number marks, with a digit; else 0.
        int cb = c * Tcs;
        int n = emon.Port.CellsAt(tc, cb + 9);
        int from = emon.Port.CellsAt(tc, cb + 8);
        int digits = 0;
        int k = 0;
        int j = 0;
        if ((n == 0) || (n > 3)) {
            return 0;
        }
        while (k < n) {
            int w = emon.Port.CellsAt(tw, from + k);
            int ts = Evidence.WdGet(wd, w, Evidence.HdTstart());
            int tl = Evidence.WdGet(wd, w, Evidence.HdTlen());
            j = 0;
            while (j < tl) {
                int cp = emon.Port.CellsAt(et, ts + j);
                if ((cp >= 48) && (cp <= 57)) {
                    digits += 1;
                } else if (!TbNumChar(cp)) {
                    return 0;
                }
                j += 1;
            }
            k += 1;
        }
        if (digits > 0) {
            return 1;
        }
        return 0;
    }
    internal static int TbCellBold(emon.Port.Cells wd, emon.Port.Cells tw, emon.Port.Cells tc, int c) {
        // 1 when every word of the cell is bold, 0 when one is not, -1 for an empty cell.
        int cb = c * Tcs;
        int n = emon.Port.CellsAt(tc, cb + 9);
        int from = emon.Port.CellsAt(tc, cb + 8);
        int k = 0;
        if (n == 0) {
            return -1;
        }
        while (k < n) {
            if ((Evidence.WdGet(wd, emon.Port.CellsAt(tw, from + k), Evidence.WfStyle()) & Model.SyBold()) == 0) {
                return 0;
            }
            k += 1;
        }
        return 1;
    }
    internal static int TbRowStat(emon.Port.Cells tc, int cfirst, int cend, int r, emon.Port.Cells wd, emon.Port.Cells et, emon.Port.Cells tw, int what) {
        // Of the cells that start in row r: what 0 how many are not empty, 1 how many are bold, 2 how many are
        // numeric, 3 how many there are.
        int c = cfirst;
        int n = 0;
        while (c < cend) {
            if (emon.Port.CellsAt(tc, c * Tcs) == r) {
                if (what == 3) {
                    n += 1;
                }
                if ((what == 0) && (emon.Port.CellsAt(tc, (c * Tcs) + 9) > 0)) {
                    n += 1;
                }
                if ((what == 1) && (TbCellBold(wd, tw, tc, c) == 1)) {
                    n += 1;
                }
                if ((what == 2) && (TbCellNumeric(wd, et, tw, tc, c) == 1)) {
                    n += 1;
                }
            }
            c += 1;
        }
        return n;
    }
    internal static bool TbRowBold(emon.Port.Cells tc, int cfirst, int cend, int r, emon.Port.Cells wd, emon.Port.Cells et, emon.Port.Cells tw) {
        // Is row r bold: it has cells and every one that is not empty is bold.
        int ne = TbRowStat(tc, cfirst, cend, r, wd, et, tw, 0);
        return (ne > 0) && (TbRowStat(tc, cfirst, cend, r, wd, et, tw, 1) == ne);
    }
    internal static int TbNumCols(emon.Port.Cells tb, int k, int r0, emon.Port.Cells wd, emon.Port.Cells et, emon.Port.Cells tc, emon.Port.Cells tw) {
        // How many columns, over the rows from r0 on, have at least 3 cells of which 4/5 are numeric.
        int b = k * Tbs;
        int ncols = emon.Port.CellsAt(tb, b + 8);
        int cfirst = emon.Port.CellsAt(tb, b + 9);
        int cend = cfirst + emon.Port.CellsAt(tb, b + 10);
        int col = 0;
        int c = 0;
        int ne = 0;
        int nn = 0;
        int total = 0;
        while (col < ncols) {
            ne = 0;
            nn = 0;
            c = cfirst;
            while (c < cend) {
                if ((emon.Port.CellsAt(tc, (c * Tcs) + 1) == col) && ((emon.Port.CellsAt(tc, c * Tcs) >= r0) && (emon.Port.CellsAt(tc, (c * Tcs) + 3) == 1))) {
                    if (emon.Port.CellsAt(tc, (c * Tcs) + 9) > 0) {
                        ne += 1;
                        if (TbCellNumeric(wd, et, tw, tc, c) == 1) {
                            nn += 1;
                        }
                    }
                }
                c += 1;
            }
            if ((ne >= 3) && ((nn * 10) >= (ne * 8))) {
                total += 1;
            }
            col += 1;
        }
        return total;
    }
    internal static int TbHeadRows(emon.Port.Cells tb, int k, emon.Port.Cells wd, emon.Port.Cells et, emon.Port.Cells tc, emon.Port.Cells tw) {
        // How many leading rows are the header: the bold ones (a table of bold rows has none, and a header is
        // at most half of the rows); else, when the first row has no number and a column below it is numeric,
        // that one row.
        int b = k * Tbs;
        int nrows = emon.Port.CellsAt(tb, b + 7);
        int cfirst = emon.Port.CellsAt(tb, b + 9);
        int cend = cfirst + emon.Port.CellsAt(tb, b + 10);
        int h = 0;
        while ((h < (nrows - 1)) && TbRowBold(tc, cfirst, cend, h, wd, et, tw)) {
            h += 1;
        }
        if ((h > 0) && ((h * 2) <= (nrows + 1))) {
            return h;
        }
        if ((nrows >= 3) && (TbRowStat(tc, cfirst, cend, 0, wd, et, tw, 2) == 0)) {
            if ((TbRowStat(tc, cfirst, cend, 0, wd, et, tw, 0) >= 2) && (TbNumCols(tb, k, 1, wd, et, tc, tw) >= 1)) {
                return 1;
            }
        }
        return 0;
    }
    internal static int TbFootRows(emon.Port.Cells tb, int k, int nhead, emon.Port.Cells wd, emon.Port.Cells et, emon.Port.Cells tc, emon.Port.Cells tw) {
        // 1 when the last row is bold and the row above it is not, with at least two body rows; else 0.
        int b = k * Tbs;
        int nrows = emon.Port.CellsAt(tb, b + 7);
        int cfirst = emon.Port.CellsAt(tb, b + 9);
        int cend = cfirst + emon.Port.CellsAt(tb, b + 10);
        if ((nrows - nhead) < 3) {
            return 0;
        }
        if (TbRowBold(tc, cfirst, cend, nrows - 1, wd, et, tw) && !TbRowBold(tc, cfirst, cend, nrows - 2, wd, et, tw)) {
            return 1;
        }
        return 0;
    }
    internal static int TbColAlign(emon.Port.Cells tb, int k, int col, int r0, int r1, emon.Port.Cells wd, emon.Port.Cells tc, emon.Port.Cells tw) {
        // The alignment (an `al` code, 0 none) of the cells of column `col` in rows r0..r1 (single-column ones),
        // decided together against their text extent (SPEC 10.10): start when every start gap is within t (a
        // quarter of the size) and the end gaps vary by more than 2t, end the other way round, center when the
        // two gaps agree within t on every cell and the start gap varies.
        int b = k * Tbs;
        int cfirst = emon.Port.CellsAt(tb, b + 9);
        int cend = cfirst + emon.Port.CellsAt(tb, b + 10);
        int c = cfirst;
        int n = 0;
        int box0 = 2000000000;
        int box1 = -2000000000;
        int size = 0;
        int smax = -2000000000;
        int smin = 2000000000;
        int emax = -2000000000;
        int emin = 2000000000;
        int cen = 1;
        int res = 0;
        while (c < cend) {
            if ((emon.Port.CellsAt(tc, (c * Tcs) + 1) == col) && ((emon.Port.CellsAt(tc, c * Tcs) >= r0) && ((emon.Port.CellsAt(tc, c * Tcs) < r1) && ((emon.Port.CellsAt(tc, (c * Tcs) + 3) == 1) && (emon.Port.CellsAt(tc, (c * Tcs) + 9) > 0))))) {
                n += 1;
                if (emon.Port.CellsAt(tc, (c * Tcs) + 13) < box0) {
                    box0 = emon.Port.CellsAt(tc, (c * Tcs) + 13);
                }
                if (emon.Port.CellsAt(tc, (c * Tcs) + 14) > box1) {
                    box1 = emon.Port.CellsAt(tc, (c * Tcs) + 14);
                }
                if (size == 0) {
                    size = Evidence.WdGet(wd, emon.Port.CellsAt(tw, emon.Port.CellsAt(tc, (c * Tcs) + 8)), Evidence.WfSize());
                }
            }
            c += 1;
        }
        if (n < 2) {
            return 0;
        }
        int t = size / 4;
        c = cfirst;
        while (c < cend) {
            if ((emon.Port.CellsAt(tc, (c * Tcs) + 1) == col) && ((emon.Port.CellsAt(tc, c * Tcs) >= r0) && ((emon.Port.CellsAt(tc, c * Tcs) < r1) && ((emon.Port.CellsAt(tc, (c * Tcs) + 3) == 1) && (emon.Port.CellsAt(tc, (c * Tcs) + 9) > 0))))) {
                int sg0 = emon.Port.CellsAt(tc, (c * Tcs) + 13) - box0;
                int eg0 = box1 - emon.Port.CellsAt(tc, (c * Tcs) + 14);
                if (sg0 > smax) {
                    smax = sg0;
                }
                if (sg0 < smin) {
                    smin = sg0;
                }
                if (eg0 > emax) {
                    emax = eg0;
                }
                if (eg0 < emin) {
                    emin = eg0;
                }
                if (TbAbs(sg0 - eg0) > t) {
                    cen = 0;
                }
            }
            c += 1;
        }
        if ((smax <= t) && ((emax - emin) > (2 * t))) {
            res = 1;
        }
        if ((res == 0) && ((emax <= t) && ((smax - smin) > (2 * t)))) {
            res = 3;
        }
        if ((res == 0) && ((cen == 1) && ((smax - smin) > (2 * t)))) {
            res = 2;
        }
        return res;
    }
    internal static int TbHeadAlign(emon.Port.Cells tb, int k, int c, int colal, emon.Port.Cells wd, emon.Port.Cells tc, emon.Port.Cells tw) {
        // The alignment of header cell c: against its cell box in a ruled table (and when it spans columns),
        // else against the extent of its column's BODY text (the header is not its own measure): centre or end when
        // the text is clear of the body's edges by 4t, start when it is flush and the column's body is start.
        int b = k * Tbs;
        int cfirst = emon.Port.CellsAt(tb, b + 9);
        int cend = cfirst + emon.Port.CellsAt(tb, b + 10);
        int cb = c * Tcs;
        int col = emon.Port.CellsAt(tc, cb + 1);
        int bx0 = emon.Port.CellsAt(tc, cb + 4);
        int bx1 = emon.Port.CellsAt(tc, cb + 6);
        int j = cfirst;
        if (emon.Port.CellsAt(tc, cb + 9) == 0) {
            return 0;
        }
        if ((emon.Port.CellsAt(tb, b + 5) != PfRuled) && (emon.Port.CellsAt(tc, cb + 3) == 1)) {
            bx0 = 2000000000;
            bx1 = -2000000000;
            while (j < cend) {
                if ((emon.Port.CellsAt(tc, (j * Tcs) + 1) == col) && ((emon.Port.CellsAt(tc, (j * Tcs) + 3) == 1) && ((emon.Port.CellsAt(tc, j * Tcs) >= emon.Port.CellsAt(tb, b + 11)) && (emon.Port.CellsAt(tc, (j * Tcs) + 9) > 0)))) {
                    if (emon.Port.CellsAt(tc, (j * Tcs) + 13) < bx0) {
                        bx0 = emon.Port.CellsAt(tc, (j * Tcs) + 13);
                    }
                    if (emon.Port.CellsAt(tc, (j * Tcs) + 14) > bx1) {
                        bx1 = emon.Port.CellsAt(tc, (j * Tcs) + 14);
                    }
                }
                j += 1;
            }
            if (bx0 > bx1) {
                return 0;
            }
        }
        int t = Evidence.WdGet(wd, emon.Port.CellsAt(tw, emon.Port.CellsAt(tc, cb + 8)), Evidence.WfSize()) / 4;
        int sg0 = emon.Port.CellsAt(tc, cb + 13) - bx0;
        int eg0 = bx1 - emon.Port.CellsAt(tc, cb + 14);
        if ((TbAbs(sg0 - eg0) <= t) && (TbMin(sg0, eg0) >= (4 * t))) {
            return 2;
        }
        if ((eg0 >= 0) && ((eg0 <= t) && (sg0 >= (4 * t)))) {
            return 3;
        }
        if ((sg0 >= 0) && ((sg0 <= t) && ((colal == 1) && (eg0 >= 0)))) {
            return 1;
        }
        return 0;
    }
    internal static int TbAligns(emon.Port.Cells tb, int k, emon.Port.Cells wd, emon.Port.Cells tc, emon.Port.Cells tw) {
        // Set the `align` of every cell of table k: the body columns together, the header cells each, the foot
        // cells as their column.
        int b = k * Tbs;
        int nrows = emon.Port.CellsAt(tb, b + 7);
        int ncols = emon.Port.CellsAt(tb, b + 8);
        int cfirst = emon.Port.CellsAt(tb, b + 9);
        int cend = cfirst + emon.Port.CellsAt(tb, b + 10);
        int nhead = emon.Port.CellsAt(tb, b + 11);
        int nfoot = emon.Port.CellsAt(tb, b + 12);
        int col = 0;
        int c = 0;
        int al = 0;
        while (col < ncols) {
            al = TbColAlign(tb, k, col, nhead, nrows - nfoot, wd, tc, tw);
            c = cfirst;
            while (c < cend) {
                if ((emon.Port.CellsAt(tc, (c * Tcs) + 1) == col) && (emon.Port.CellsAt(tc, (c * Tcs) + 3) == 1)) {
                    if (emon.Port.CellsAt(tc, c * Tcs) >= nhead) {
                        emon.Port.CellsSet(tc, (c * Tcs) + 11, al);
                    } else {
                        int ha = TbHeadAlign(tb, k, c, al, wd, tc, tw);
                        emon.Port.CellsSet(tc, (c * Tcs) + 11, ha);
                    }
                }
                c += 1;
            }
            col += 1;
        }
        c = cfirst;
        while (c < cend) {
            if ((emon.Port.CellsAt(tc, c * Tcs) < nhead) && (emon.Port.CellsAt(tc, (c * Tcs) + 3) > 1)) {
                int ha = TbHeadAlign(tb, k, c, 0, wd, tc, tw);
                emon.Port.CellsSet(tc, (c * Tcs) + 11, ha);
            }
            c += 1;
        }
        return 0;
    }
