    internal static int TbLower(int cp) {
        if ((cp >= 65) && (cp <= 90)) {
            return cp + 32;
        }
        return cp;
    }
    internal static bool TbIsLabelWord(emon.Port.Cells wd, emon.Port.Cells et, int w) {
        // Is the word a table keyword (any case, a trailing full stop ignored): Table, Tab., Tabelle, Tableau...
        int ts = Evidence.WdGet(wd, w, Evidence.HdTstart());
        int tl = Evidence.WdGet(wd, w, Evidence.HdTlen());
        int r = 0;
        int j = 0;
        int same = 1;
        if (tl < 1) {
            return 0 == 1;
        }
        if (emon.Port.CellsAt(et, ts + (tl - 1)) == 46) {
            tl -= 1;
        }
        while (r < 9) {
            if (TbKw[r * 9 + 0] == tl) {
                same = 1;
                j = 0;
                while (j < tl) {
                    if (TbLower(emon.Port.CellsAt(et, ts + j)) != TbKw[r * 9 + (j + 1)]) {
                        same = 0;
                    }
                    j += 1;
                }
                if (same == 1) {
                    return 1 == 1;
                }
            }
            r += 1;
        }
        return 0 == 1;
    }
    internal static bool TbIsLabelNumber(emon.Port.Cells wd, emon.Port.Cells et, int w) {
        // A table number: starts with a digit, or a capital letter and a digit (S1).
        int ts = Evidence.WdGet(wd, w, Evidence.HdTstart());
        int tl = Evidence.WdGet(wd, w, Evidence.HdTlen());
        if (tl < 1) {
            return 0 == 1;
        }
        int c0 = emon.Port.CellsAt(et, ts);
        if ((c0 >= 48) && (c0 <= 57)) {
            return 1 == 1;
        }
        if ((tl >= 2) && ((c0 >= 65) && (c0 <= 90))) {
            int c1 = emon.Port.CellsAt(et, ts + 1);
            return (c1 >= 48) && (c1 <= 57);
        }
        return 0 == 1;
    }
    internal static bool TbLineLabel(emon.Port.Cells wd, emon.Port.Cells et, emon.Port.Cells ln, int l) {
        // Does line l start with a table keyword and a table number.
        int w0 = Evidence.LnGet(ln, l, Evidence.LhFirst());
        if (Evidence.LnGet(ln, l, Evidence.LhCount()) < 2) {
            return 0 == 1;
        }
        return TbIsLabelWord(wd, et, w0) && TbIsLabelNumber(wd, et, w0 + 1);
    }
    internal static int TbCaption(emon.Port.Cells tb, int k, emon.Port.Cells wd, emon.Port.Cells et, emon.Port.Cells ln, int l0, int l1, emon.Port.Cells tq) {
        // Find the caption of table k among the unclaimed lines l0..l1: a line that starts with a table keyword
        // and a number, over the table or under it within two and a half line heights, preferring the one over it;
        // the lines on its baseline to its right and the lines under it that continue it are part of it. They are
        // claimed and their numbers pushed on `tq` (qfirst, qcount in the table's cells 14 and 15).
        int b = k * Tbs;
        int tx0 = emon.Port.CellsAt(tb, b + 1);
        int ty0 = emon.Port.CellsAt(tb, b + 2);
        int tx1 = emon.Port.CellsAt(tb, b + 3);
        int ty1 = emon.Port.CellsAt(tb, b + 4);
        int l = l0;
        int best = -1;
        int bestd = 2000000000;
        int above = 0;
        while (l < l1) {
            if (Evidence.LnGet(ln, l, 15) == 0) {
                if (TbLineLabel(wd, et, ln, l)) {
                    if ((Evidence.LnGet(ln, l, Evidence.LhX0()) < tx1) && (Evidence.LnGet(ln, l, Evidence.LhX1()) > tx0)) {
                        int lht = Evidence.LnGet(ln, l, Evidence.LhY1()) - Evidence.LnGet(ln, l, Evidence.LhY0());
                        int da = ty0 - Evidence.LnGet(ln, l, Evidence.LhY1());
                        int db = Evidence.LnGet(ln, l, Evidence.LhY0()) - ty1;
                        if ((da >= -300) && ((da * 2) <= (lht * 5))) {
                            if (TbAbs(da) < bestd) {
                                best = l;
                                bestd = TbAbs(da);
                                above = 1;
                            }
                        }
                        if ((db >= -300) && (((db * 2) <= (lht * 5)) && (above == 0))) {
                            if (TbAbs(db) < bestd) {
                                best = l;
                                bestd = TbAbs(db);
                            }
                        }
                    }
                }
            }
            l += 1;
        }
        if (best < 0) {
            return 0;
        }
        emon.Port.CellsSet(tb, b + 14, emon.Port.CellsLen(tq));
        emon.Port.CellsPush(tq, best);
        Evidence.LnSet(ln, best, 15, TbHeld + k);
        int h = Evidence.LnGet(ln, best, Evidence.LhY1()) - Evidence.LnGet(ln, best, Evidence.LhY0());
        int curx1 = Evidence.LnGet(ln, best, Evidence.LhX1());
        int cury1 = Evidence.LnGet(ln, best, Evidence.LhY1());
        int more = 1;
        int rounds = 0;
        int pick = -1;
        l = l0;
        while (l < l1) {
            if (Evidence.LnGet(ln, l, 15) == 0) {
                if ((Evidence.LnGet(ln, l, Evidence.LhX0()) > (curx1 - 100)) && ((Evidence.LnGet(ln, l, Evidence.LhX0()) - curx1) <= (2 * h))) {
                    if (TbAbs(Evidence.LnGet(ln, l, Evidence.LhBy0()) - Evidence.LnGet(ln, best, Evidence.LhBy0())) <= (h / 3)) {
                        emon.Port.CellsPush(tq, l);
                        Evidence.LnSet(ln, l, 15, TbHeld + k);
                        curx1 = Evidence.LnGet(ln, l, Evidence.LhX1());
                    }
                }
            }
            l += 1;
        }
        while ((more == 1) && (rounds < 6)) {
            more = 0;
            rounds += 1;
            pick = -1;
            l = l0;
            while (l < l1) {
                if (Evidence.LnGet(ln, l, 15) == 0) {
                    if ((Evidence.LnGet(ln, l, Evidence.LhY0()) >= (cury1 - 200)) && ((Evidence.LnGet(ln, l, Evidence.LhY0()) - cury1) <= ((h * 3) / 5))) {
                        if ((Evidence.LnGet(ln, l, Evidence.LhX0()) < tx1) && (Evidence.LnGet(ln, l, Evidence.LhX1()) > tx0)) {
                            if (!TbLineLabel(wd, et, ln, l)) {
                                if (Evidence.LnGet(ln, l, Evidence.LhY1()) < (ty0 + 300)) {
                                    if (pick < 0) {
                                        pick = l;
                                    }
                                }
                            }
                        }
                    }
                }
                l += 1;
            }
            if ((pick >= 0) && (above == 1)) {
                emon.Port.CellsPush(tq, pick);
                Evidence.LnSet(ln, pick, 15, TbHeld + k);
                cury1 = Evidence.LnGet(ln, pick, Evidence.LhY1());
                more = 1;
            }
        }
        emon.Port.CellsSet(tb, b + 15, emon.Port.CellsLen(tq) - emon.Port.CellsAt(tb, b + 14));
        return 1;
    }
    internal static int TbReject(emon.Port.Cells tb, emon.Port.Cells tc, emon.Port.Cells tw, emon.Port.Cells tx, int nt, int c0, int w0, int x0) {
        // Forget the candidate that was just built: every arena goes back to the length it had.
        emon.Port.CellsDrop(tb, nt * Tbs);
        emon.Port.CellsDrop(tc, c0 * Tcs);
        emon.Port.CellsDrop(tw, w0);
        emon.Port.CellsDrop(tx, x0);
        return 0;
    }
    internal static int TbTabularRows(emon.Port.Cells tb, int k, emon.Port.Cells tc) {
        // How many rows of table k have two cells or more with text.
        int b = k * Tbs;
        int cfirst = emon.Port.CellsAt(tb, b + 9);
        int cend = cfirst + emon.Port.CellsAt(tb, b + 10);
        int c = cfirst;
        int row = -1;
        int cnt = 0;
        int total = 0;
        while (c < cend) {
            if (emon.Port.CellsAt(tc, c * Tcs) != row) {
                if (cnt >= 2) {
                    total += 1;
                }
                row = emon.Port.CellsAt(tc, c * Tcs);
                cnt = 0;
            }
            if (emon.Port.CellsAt(tc, (c * Tcs) + 9) > 0) {
                cnt += 1;
            }
            c += 1;
        }
        if (cnt >= 2) {
            total += 1;
        }
        return total;
    }
    internal static int TbScore(emon.Port.Cells tb, int k, emon.Port.Cells wd, emon.Port.Cells et, emon.Port.Cells tc, emon.Port.Cells tw) {
        // The score (0 to 1000, 0 = not a table) of text-based candidate k of its profile (SPEC 10.5): prose in
        // columns is not a table, so cells that are long, or that end like sentences, refuse it. The whitespace
        // profile has no rules or fills to vouch for it and asks for more: three columns or a numeric column, and a header.
        int b = k * Tbs;
        int prof = emon.Port.CellsAt(tb, b + 5);
        int ncols = emon.Port.CellsAt(tb, b + 8);
        int nrows = emon.Port.CellsAt(tb, b + 7);
        int cfirst = emon.Port.CellsAt(tb, b + 9);
        int cend = cfirst + emon.Port.CellsAt(tb, b + 10);
        int c = cfirst;
        int ne = 0;
        int nw = 0;
        int nlong = 0;
        int nend = 0;
        int nprose = 0;
        int score = 0;
        while (c < cend) {
            int cn = emon.Port.CellsAt(tc, (c * Tcs) + 9);
            if (cn > 0) {
                ne += 1;
                nw += cn;
                if (cn > 8) {
                    nlong += 1;
                }
                if (cn >= 2) {
                    int fw = emon.Port.CellsAt(tw, emon.Port.CellsAt(tc, (c * Tcs) + 8));
                    int lw2 = emon.Port.CellsAt(tw, emon.Port.CellsAt(tc, (c * Tcs) + 8) + (cn - 1));
                    int c0 = emon.Port.CellsAt(et, Evidence.WdGet(wd, fw, Evidence.HdTstart()));
                    int ts2 = Evidence.WdGet(wd, lw2, Evidence.HdTstart());
                    int tl2 = Evidence.WdGet(wd, lw2, Evidence.HdTlen());
                    if ((c0 >= 97) && (c0 <= 122)) {
                        nprose += 1;
                    }
                    if ((tl2 > 1) && (emon.Port.CellsAt(et, ts2 + (tl2 - 1)) == 45)) {
                        nprose += 1;
                    }
                }
                if (cn >= 3) {
                    int lw = emon.Port.CellsAt(tw, emon.Port.CellsAt(tc, (c * Tcs) + 8) + (cn - 1));
                    int ts = Evidence.WdGet(wd, lw, Evidence.HdTstart());
                    int tl = Evidence.WdGet(wd, lw, Evidence.HdTlen());
                    if ((tl > 0) && (emon.Port.CellsAt(et, ts + (tl - 1)) == 46)) {
                        nend += 1;
                    }
                }
            }
            c += 1;
        }
        if (ne < 4) {
            return 0;
        }
        if ((nprose * 10) > (ne * 3)) {
            return 0;
        }
        if ((prof == PfWhitespace) && ((ne * 100) < ((nrows * ncols) * 55))) {
            return 0;
        }
        if ((ne * 100) < ((nrows * ncols) * 35)) {
            return 0;
        }
        if ((nend * 5) > (ne * 2)) {
            return 0;
        }
        if ((nlong * 5) > ne) {
            return 0;
        }
        if (prof == PfWhitespace) {
            if ((nw * 10) > (ne * 40)) {
                return 0;
            }
            score = 400;
            if (ncols >= 3) {
                score += 100;
            }
            if (TbNumCols(tb, k, 1, wd, et, tc, tw) >= 1) {
                score += 100;
            }
            if (TbHeadRows(tb, k, wd, et, tc, tw) >= 1) {
                score += 100;
            }
            if (nrows >= 4) {
                score += 50;
            }
            if ((ncols == 2) && ((nrows >= 3) && ((TbNumCols(tb, k, 1, wd, et, tc, tw) == 1) && ((nw * 10) <= (ne * 25))))) {
                score += 100;
            }
            if (score < 600) {
                return 0;
            }
            return score;
        }
        if ((nw * 10) > (ne * 80)) {
            return 0;
        }
        if (prof == PfPartial) {
            return 800 + ((90 * TbTabularRows(tb, k, tc)) / TbMax(1, nrows));
        }
        return 750 + ((40 * TbTabularRows(tb, k, tc)) / TbMax(1, nrows));
    }
    internal static int TbFirstRow(emon.Port.Cells rw, int nr, int y0) {
        // The first row of a partial candidate: the first row whose centre is below the top rule y0, and the
        // tabular rows (at most three) directly above it, which are the header when the rule is the one under it.
        int ra = 0;
        int n = 0;
        while ((ra < nr) && (((emon.Port.CellsAt(rw, (ra * Rws) + 6) + emon.Port.CellsAt(rw, (ra * Rws) + 7)) / 2) < y0)) {
            ra += 1;
        }
        while ((ra > 0) && ((ra < nr) && ((n < 3) && ((emon.Port.CellsAt(rw, ((ra - 1) * Rws) + 9) >= 2) && ((10 * (emon.Port.CellsAt(rw, (ra * Rws) + 2) - emon.Port.CellsAt(rw, ((ra - 1) * Rws) + 2))) <= (24 * emon.Port.CellsAt(rw, (ra * Rws) + 3))))))) {
            ra -= 1;
            n += 1;
        }
        return ra;
    }
    internal static int TbPartialTry(emon.Port.Cells wd, emon.Port.Cells et, int w0, int w1, int page, int ex0, int ex1, int ya, int yb, emon.Port.Cells wl, emon.Port.Cells rw, emon.Port.Cells sg, emon.Port.Cells ch, emon.Port.Cells st, emon.Port.Cells en, emon.Port.Cells rmap, emon.Port.Cells gm, emon.Port.Cells gs, emon.Port.Cells ry, emon.Port.Cells pr, emon.Port.Cells so, emon.Port.Cells tb, emon.Port.Cells tc, emon.Port.Cells tw, emon.Port.Cells tx) {
        // One partial candidate: the words between the rules at ya and yb (and the tabular rows directly above ya),
        // columns from their channels; kept when it scores.
        int nr = TbRows(wd, w0, w1, ex0 - PosTol, ya - 9000, ex1 + PosTol, yb, wl, rw, sg);
        int ra = TbFirstRow(rw, nr, ya);
        int nt = TbRowsOf(tb, Tbs);
        int c0 = TbRowsOf(tc, Tcs);
        int wl0 = emon.Port.CellsLen(tw);
        int xl0 = emon.Port.CellsLen(tx);
        if ((nr - ra) >= 3) {
            int t = TbTextGrid(wd, wl, rw, sg, ch, st, en, rmap, gm, gs, ry, pr, so, tb, tc, tw, tx, page, ra, nr, PfPartial, 850, 0, ex0, ya, ex1, yb);
            if (t >= 0) {
                int sc = TbScore(tb, t, wd, et, tc, tw);
                if (sc == 0) {
                    TbReject(tb, tc, tw, tx, nt, c0, wl0, xl0);
                } else {
                    emon.Port.CellsSet(tb, (t * Tbs) + 6, sc);
                }
            }
        }
        return 0;
    }
    internal static int TbPartialPage(emon.Port.Cells rm, int page, emon.Port.Cells wd, emon.Port.Cells et, int w0, int w1, emon.Port.Cells used, emon.Port.Cells wl, emon.Port.Cells rw, emon.Port.Cells sg, emon.Port.Cells ch, emon.Port.Cells st, emon.Port.Cells en, emon.Port.Cells rmap, emon.Port.Cells gm, emon.Port.Cells gs, emon.Port.Cells ry, emon.Port.Cells pr, emon.Port.Cells so, emon.Port.Cells tb, emon.Port.Cells tc, emon.Port.Cells tw, emon.Port.Cells tx) {
        // Chains of horizontal rules of one extent (booktabs: top, mid, bottom) are partial candidates: the
        // words between the first and the last rule, columns from the channels of their text.
        int n = TbRowsOf(rm, Rls);
        int nh = 0;
        int i = 0;
        int j = 0;
        int cnt = 0;
        int ex0 = 0;
        int ex1 = 0;
        int m = 0;
        int last = 0;
        while ((nh < n) && (emon.Port.CellsAt(rm, nh * Rls) == 0)) {
            nh += 1;
        }
        emon.Port.CellsDrop(used, 0);
        while (i < nh) {
            emon.Port.CellsPush(used, 0);
            i += 1;
        }
        i = 0;
        while (i < nh) {
            if ((emon.Port.CellsAt(used, i) == 0) && ((emon.Port.CellsAt(rm, (i * Rls) + 3) - emon.Port.CellsAt(rm, (i * Rls) + 2)) >= 3000)) {
                cnt = 1;
                ex0 = emon.Port.CellsAt(rm, (i * Rls) + 2);
                ex1 = emon.Port.CellsAt(rm, (i * Rls) + 3);
                last = emon.Port.CellsAt(rm, (i * Rls) + 1);
                emon.Port.CellsSet(used, i, 1);
                emon.Port.CellsPush(used, emon.Port.CellsAt(rm, (i * Rls) + 1));
                j = i + 1;
                while ((j < nh) && ((emon.Port.CellsAt(rm, (j * Rls) + 1) - last) <= 30000)) {
                    if (emon.Port.CellsAt(used, j) == 0) {
                        int a0 = emon.Port.CellsAt(rm, (j * Rls) + 2);
                        int a1 = emon.Port.CellsAt(rm, (j * Rls) + 3);
                        int ov = TbMin(ex1, a1) - TbMax(ex0, a0);
                        int lj = a1 - a0;
                        if ((lj >= 2000) && (((ov * 10) >= (lj * 6)) && ((ov * 10) >= ((ex1 - ex0) * 3)))) {
                            cnt += 1;
                            last = emon.Port.CellsAt(rm, (j * Rls) + 1);
                            if (a0 < ex0) {
                                ex0 = a0;
                            }
                            if (a1 > ex1) {
                                ex1 = a1;
                            }
                            emon.Port.CellsSet(used, j, 1);
                            emon.Port.CellsPush(used, emon.Port.CellsAt(rm, (j * Rls) + 1));
                        }
                    }
                    j += 1;
                }
                if (cnt >= 2) {
                    TbPartialTry(wd, et, w0, w1, page, ex0, ex1, emon.Port.CellsAt(rm, (i * Rls) + 1), last, wl, rw, sg, ch, st, en, rmap, gm, gs, ry, pr, so, tb, tc, tw, tx);
                    if (cnt >= 3) {
                        m = nh;
                        while ((m + 1) < emon.Port.CellsLen(used)) {
                            TbPartialTry(wd, et, w0, w1, page, ex0, ex1, emon.Port.CellsAt(used, m), emon.Port.CellsAt(used, m + 1), wl, rw, sg, ch, st, en, rmap, gm, gs, ry, pr, so, tb, tc, tw, tx);
                            m += 1;
                        }
                    }
                }
                emon.Port.CellsDrop(used, nh);
            }
            i += 1;
        }
        return 0;
    }
    internal static int TbBands(emon.Port.Cells fl, emon.Port.Cells so, emon.Port.Cells bd) {
        // The page's fills (`fl`) grouped into bands of one top and bottom (`bd`, stride 6: y0 y1 x0 x1 colour n),
        // in order of their tops. Answers how many bands.
        int n = TbRowsOf(fl, 6);
        int i = 0;
        emon.Port.CellsDrop(so, 0);
        emon.Port.CellsDrop(bd, 0);
        while (i < n) {
            emon.Port.CellsPush(so, i);
            i += 1;
        }
        TbSortIdx(so, fl, 6, 1, 0);
        i = 0;
        while (i < n) {
            int f = emon.Port.CellsAt(so, i);
            int x0 = emon.Port.CellsAt(fl, f * 6);
            int y0 = emon.Port.CellsAt(fl, (f * 6) + 1);
            int x1 = emon.Port.CellsAt(fl, (f * 6) + 2);
            int y1 = emon.Port.CellsAt(fl, (f * 6) + 3);
            int nb = TbRowsOf(bd, 6);
            if ((nb > 0) && ((TbAbs(y0 - emon.Port.CellsAt(bd, (nb - 1) * 6)) <= 150) && ((TbAbs(y1 - emon.Port.CellsAt(bd, ((nb - 1) * 6) + 1)) <= 150) && (x0 <= (emon.Port.CellsAt(bd, ((nb - 1) * 6) + 3) + 300))))) {
                int lb = (nb - 1) * 6;
                if (x0 < emon.Port.CellsAt(bd, lb + 2)) {
                    emon.Port.CellsSet(bd, lb + 2, x0);
                }
                if (x1 > emon.Port.CellsAt(bd, lb + 3)) {
                    emon.Port.CellsSet(bd, lb + 3, x1);
                }
                emon.Port.CellsSet(bd, lb + 5, emon.Port.CellsAt(bd, lb + 5) + 1);
            } else {
                emon.Port.CellsPush(bd, y0);
                emon.Port.CellsPush(bd, y1);
                emon.Port.CellsPush(bd, x0);
                emon.Port.CellsPush(bd, x1);
                emon.Port.CellsPush(bd, emon.Port.CellsAt(fl, (f * 6) + 4));
                emon.Port.CellsPush(bd, 1);
            }
            i += 1;
        }
        return TbRowsOf(bd, 6);
    }
    internal static int TbBandMember(emon.Port.Cells bd, emon.Port.Cells used, int b0, int b1, int y) {
        // The band of b0..b1 that belongs to the stack being built (used = 2) and whose top and bottom hold y.
        int i = b0;
        while (i <= b1) {
            if ((emon.Port.CellsAt(used, i) == 2) && ((y >= emon.Port.CellsAt(bd, i * 6)) && (y <= emon.Port.CellsAt(bd, (i * 6) + 1)))) {
                return i;
            }
            i += 1;
        }
        return -1;
    }
    internal static int TbShadedPage(emon.Port.Cells fl, int page, emon.Port.Cells wd, emon.Port.Cells et, int w0, int w1, emon.Port.Cells bd, emon.Port.Cells used, emon.Port.Cells wl, emon.Port.Cells rw, emon.Port.Cells sg, emon.Port.Cells ch, emon.Port.Cells st, emon.Port.Cells en, emon.Port.Cells rmap, emon.Port.Cells gm, emon.Port.Cells gs, emon.Port.Cells ry, emon.Port.Cells pr, emon.Port.Cells so, emon.Port.Cells tb, emon.Port.Cells tc, emon.Port.Cells tw, emon.Port.Cells tx) {
        // Stacks of three or more bands of one extent, each starting where the one before ended or one row
        // later, with two colours or a gap (zebra), are shaded candidates: a band is a row (several baselines may
        // be in one), a baseline row that is in no band is a row of its own, columns from the channels.
        int nb = TbBands(fl, so, bd);
        int i = 0;
        int j = 0;
        int cnt = 0;
        int last = 0;
        int ncol = 0;
        int gapseen = 0;
        emon.Port.CellsDrop(used, 0);
        while (i < nb) {
            emon.Port.CellsPush(used, 0);
            i += 1;
        }
        i = 0;
        while (i < nb) {
            if (emon.Port.CellsAt(used, i) == 0) {
                int sx0 = emon.Port.CellsAt(bd, (i * 6) + 2);
                int sx1 = emon.Port.CellsAt(bd, (i * 6) + 3);
                int colour0 = emon.Port.CellsAt(bd, (i * 6) + 4);
                cnt = 1;
                last = i;
                ncol = 1;
                gapseen = 0;
                emon.Port.CellsSet(used, i, 2);
                j = i + 1;
                while ((j < nb) && ((emon.Port.CellsAt(bd, j * 6) - emon.Port.CellsAt(bd, (last * 6) + 1)) <= 3000)) {
                    if ((emon.Port.CellsAt(used, j) == 0) && ((TbAbs(emon.Port.CellsAt(bd, (j * 6) + 2) - sx0) <= 400) && (TbAbs(emon.Port.CellsAt(bd, (j * 6) + 3) - sx1) <= 400))) {
                        int g = emon.Port.CellsAt(bd, j * 6) - emon.Port.CellsAt(bd, (last * 6) + 1);
                        int hj = emon.Port.CellsAt(bd, (j * 6) + 1) - emon.Port.CellsAt(bd, j * 6);
                        if ((g >= -150) && ((g * 5) <= (hj * 6))) {
                            emon.Port.CellsSet(used, j, 2);
                            cnt += 1;
                            if (g > 150) {
                                gapseen = 1;
                            }
                            if (emon.Port.CellsAt(bd, (j * 6) + 4) != colour0) {
                                ncol = 2;
                            }
                            last = j;
                        }
                    }
                    j += 1;
                }
                if ((cnt >= 3) && ((ncol == 2) || (gapseen == 1))) {
                    int y0 = emon.Port.CellsAt(bd, i * 6);
                    int y1 = emon.Port.CellsAt(bd, (last * 6) + 1);
                    int nr = TbRows(wd, w0, w1, sx0, y0, sx1, y1, wl, rw, sg);
                    int nt = TbRowsOf(tb, Tbs);
                    int c0 = TbRowsOf(tc, Tcs);
                    int wl0 = emon.Port.CellsLen(tw);
                    int xl0 = emon.Port.CellsLen(tx);
                    int r = 0;
                    int trow = -1;
                    int prevkey = -999999;
                    int key = 0;
                    if (nr >= 3) {
                        emon.Port.CellsDrop(rmap, 0);
                        while (r < nr) {
                            key = TbBandMember(bd, used, i, last, (emon.Port.CellsAt(rw, (r * Rws) + 6) + emon.Port.CellsAt(rw, (r * Rws) + 7)) / 2);
                            if (key < 0) {
                                key = (0 - r) - 10;
                            }
                            if (key != prevkey) {
                                trow += 1;
                                prevkey = key;
                            }
                            emon.Port.CellsPush(rmap, trow);
                            r += 1;
                        }
                        int t = TbTextGrid(wd, wl, rw, sg, ch, st, en, rmap, gm, gs, ry, pr, so, tb, tc, tw, tx, page, 0, nr, PfShaded, 800, 1, sx0, y0, sx1, y1);
                        if (t >= 0) {
                            int sc = TbScore(tb, t, wd, et, tc, tw);
                            if (sc == 0) {
                                TbReject(tb, tc, tw, tx, nt, c0, wl0, xl0);
                            } else {
                                emon.Port.CellsSet(tb, (t * Tbs) + 6, sc);
                            }
                        }
                    }
                }
                j = i;
                while (j <= last) {
                    if (emon.Port.CellsAt(used, j) == 2) {
                        emon.Port.CellsSet(used, j, 1);
                    }
                    j += 1;
                }
            }
            i += 1;
        }
        return 0;
    }
    internal static int TbWhitespacePage(int page, emon.Port.Cells wd, emon.Port.Cells et, int w0, int w1, emon.Port.Cells wl, emon.Port.Cells rw, emon.Port.Cells sg, emon.Port.Cells ch, emon.Port.Cells st, emon.Port.Cells en, emon.Port.Cells rmap, emon.Port.Cells gm, emon.Port.Cells gs, emon.Port.Cells ry, emon.Port.Cells pr, emon.Port.Cells so, emon.Port.Cells tb, emon.Port.Cells tc, emon.Port.Cells tw, emon.Port.Cells tx) {
        // The rows of the whole page, in runs of rows that are cut in two or more chunks (a row of one chunk
        // goes in a run when a row of two follows it), each run of three such rows or more a whitespace candidate.
        int nr = TbRows(wd, w0, w1, -2000000000, -2000000000, 2000000000, 2000000000, wl, rw, sg);
        int i = 0;
        int j = 0;
        int k = 0;
        int ntab = 0;
        int more = 1;
        while (i < nr) {
            if (emon.Port.CellsAt(rw, (i * Rws) + 9) >= 2) {
                j = i;
                ntab = 1;
                more = 1;
                while (more == 1) {
                    k = j + 1;
                    if (k >= nr) {
                        more = 0;
                    } else {
                        int gapk = emon.Port.CellsAt(rw, (k * Rws) + 2) - emon.Port.CellsAt(rw, (j * Rws) + 2);
                        int szk = emon.Port.CellsAt(rw, (k * Rws) + 3);
                        if ((gapk * 10) > (szk * 30)) {
                            more = 0;
                        } else if (emon.Port.CellsAt(rw, (k * Rws) + 9) >= 2) {
                            j = k;
                            ntab += 1;
                        } else if ((emon.Port.CellsAt(rw, (k * Rws) + 9) == 1) && ((k + 1) < nr)) {
                            if (emon.Port.CellsAt(rw, ((k + 1) * Rws) + 9) >= 2) {
                                j = k;
                            } else {
                                more = 0;
                            }
                        } else {
                            more = 0;
                        }
                    }
                }
                while ((j > i) && (emon.Port.CellsAt(rw, (j * Rws) + 9) < 2)) {
                    j -= 1;
                }
                if (ntab >= 3) {
                    int nt = TbRowsOf(tb, Tbs);
                    int c0 = TbRowsOf(tc, Tcs);
                    int wl0 = emon.Port.CellsLen(tw);
                    int xl0 = emon.Port.CellsLen(tx);
                    int t = TbTextGrid(wd, wl, rw, sg, ch, st, en, rmap, gm, gs, ry, pr, so, tb, tc, tw, tx, page, i, j + 1, PfWhitespace, 0, 0, 2000000000, 2000000000, -2000000000, -2000000000);
                    if (t >= 0) {
                        int sc = TbScore(tb, t, wd, et, tc, tw);
                        if (sc == 0) {
                            TbReject(tb, tc, tw, tx, nt, c0, wl0, xl0);
                        } else {
                            emon.Port.CellsSet(tb, (t * Tbs) + 6, sc);
                        }
                    }
                }
            } else {
                j = i;
            }
            i = j + 1;
        }
        return 0;
    }
    internal static bool TbBodyLineOutside(emon.Port.Cells ln, int page, int y0, int y1, int zlo, int zhi) {
        // Is there a line, not claimed by a table, on `page` whose centre is in y0..y1 and outside the furniture
        // zones (above zlo, below zhi)?
        int n = Evidence.LnCount(ln);
        int l = 0;
        while (l < n) {
            if ((Evidence.LnGet(ln, l, Evidence.LhPage()) == page) && (Evidence.LnGet(ln, l, 15) == 0)) {
                int cy = (Evidence.LnGet(ln, l, Evidence.LhY0()) + Evidence.LnGet(ln, l, Evidence.LhY1())) / 2;
                if ((cy >= y0) && ((cy <= y1) && ((cy > zlo) && (cy < zhi)))) {
                    return 1 == 1;
                }
            }
            l += 1;
        }
        return 0 == 1;
    }
    internal static bool TbSameColumns(emon.Port.Cells tb, int a, int b, emon.Port.Cells tx) {
        // The same number of columns, every boundary of b within 1/60 of the width of a's (at least 5 pt) of a's.
        int na = emon.Port.CellsAt(tb, (a * Tbs) + 17);
        int nb = emon.Port.CellsAt(tb, (b * Tbs) + 17);
        int xa = emon.Port.CellsAt(tb, (a * Tbs) + 16);
        int xb = emon.Port.CellsAt(tb, (b * Tbs) + 16);
        int i = 0;
        if (na != nb) {
            return 0 == 1;
        }
        if (na < 3) {
            return 0 == 1;
        }
        int tol = TbMax(500, (emon.Port.CellsAt(tx, xa + (na - 1)) - emon.Port.CellsAt(tx, xa)) / 60);
        while (i < na) {
            if (TbAbs(emon.Port.CellsAt(tx, xa + i) - emon.Port.CellsAt(tx, xb + i)) > tol) {
                return 0 == 1;
            }
            i += 1;
        }
        return 1 == 1;
    }
    internal static bool TbWordSame(emon.Port.Cells wd, emon.Port.Cells et, int a, int b) {
        int n = Evidence.WdGet(wd, a, Evidence.HdTlen());
        int sa = Evidence.WdGet(wd, a, Evidence.HdTstart());
        int sb = Evidence.WdGet(wd, b, Evidence.HdTstart());
        int i = 0;
        if (n != Evidence.WdGet(wd, b, Evidence.HdTlen())) {
            return 0 == 1;
        }
        while (i < n) {
            if (emon.Port.CellsAt(et, sa + i) != emon.Port.CellsAt(et, sb + i)) {
                return 0 == 1;
            }
            i += 1;
        }
        return 1 == 1;
    }
    internal static bool TbRowSame(emon.Port.Cells tb, int a, int ra, int b, int rb, emon.Port.Cells tc, emon.Port.Cells tw, emon.Port.Cells wd, emon.Port.Cells et) {
        // Does row ra of table a say, cell for cell and word for word, what row rb of table b says.
        int ca0 = emon.Port.CellsAt(tb, (a * Tbs) + 9);
        int ca1 = ca0 + emon.Port.CellsAt(tb, (a * Tbs) + 10);
        int cb0 = emon.Port.CellsAt(tb, (b * Tbs) + 9);
        int cb1 = cb0 + emon.Port.CellsAt(tb, (b * Tbs) + 10);
        int i = ca0;
        int j = cb0;
        int k = 0;
        while ((i < ca1) && (emon.Port.CellsAt(tc, i * Tcs) != ra)) {
            i += 1;
        }
        while ((j < cb1) && (emon.Port.CellsAt(tc, j * Tcs) != rb)) {
            j += 1;
        }
        while ((i < ca1) && ((j < cb1) && ((emon.Port.CellsAt(tc, i * Tcs) == ra) && (emon.Port.CellsAt(tc, j * Tcs) == rb)))) {
            if ((emon.Port.CellsAt(tc, (i * Tcs) + 1) != emon.Port.CellsAt(tc, (j * Tcs) + 1)) || (emon.Port.CellsAt(tc, (i * Tcs) + 9) != emon.Port.CellsAt(tc, (j * Tcs) + 9))) {
                return 0 == 1;
            }
            k = 0;
            while (k < emon.Port.CellsAt(tc, (i * Tcs) + 9)) {
                if (!TbWordSame(wd, et, emon.Port.CellsAt(tw, emon.Port.CellsAt(tc, (i * Tcs) + 8) + k), emon.Port.CellsAt(tw, emon.Port.CellsAt(tc, (j * Tcs) + 8) + k))) {
                    return 0 == 1;
                }
                k += 1;
            }
            i += 1;
            j += 1;
        }
        return ((i >= ca1) || (emon.Port.CellsAt(tc, i * Tcs) != ra)) && ((j >= cb1) || (emon.Port.CellsAt(tc, j * Tcs) != rb));
    }
    internal static bool TbCaptionAgain(emon.Port.Cells tb, int a, int b, emon.Port.Cells wd, emon.Port.Cells et, emon.Port.Cells ln, emon.Port.Cells tq) {
        // Does table b have a caption, and is it the label (keyword and number) of table a's?
        int qa = emon.Port.CellsAt(tb, (a * Tbs) + 15);
        if (qa == 0) {
            return 0 == 1;
        }
        int wa = Evidence.LnGet(ln, emon.Port.CellsAt(tq, emon.Port.CellsAt(tb, (a * Tbs) + 14)), Evidence.LhFirst());
        int wb = Evidence.LnGet(ln, emon.Port.CellsAt(tq, emon.Port.CellsAt(tb, (b * Tbs) + 14)), Evidence.LhFirst());
        return TbWordSame(wd, et, wa, wb) && TbWordSame(wd, et, wa + 1, wb + 1);
    }
    internal static int TbUnfoot(emon.Port.Cells tb, int a, emon.Port.Cells tc) {
        // A table that goes on has no foot on this page: its bold last row is a row.
        int b = a * Tbs;
        int nrows = emon.Port.CellsAt(tb, b + 7);
        int nfoot = emon.Port.CellsAt(tb, b + 12);
        int cfirst = emon.Port.CellsAt(tb, b + 9);
        int cend = cfirst + emon.Port.CellsAt(tb, b + 10);
        int c = cfirst;
        while (c < cend) {
            if (emon.Port.CellsAt(tc, c * Tcs) >= (nrows - nfoot)) {
                emon.Port.CellsSet(tc, (c * Tcs) + 10, 0);
            }
            c += 1;
        }
        emon.Port.CellsSet(tb, b + 12, 0);
        return 0;
    }
    internal static int TbLink(emon.Port.Cells tb, emon.Port.Cells tc, emon.Port.Cells tw, emon.Port.Cells tx, emon.Port.Cells tq, emon.Port.Cells wd, emon.Port.Cells et, emon.Port.Cells ln, emon.Port.Cells pages) {
        // Link the fragments of tables that go on across a page break (see the head of this section).
        int n = TbRowsOf(tb, Tbs);
        int j = 1;
        int a = 0;
        int head = 0;
        int h = 0;
        int ok = 0;
        int skip = 0;
        int span = 0;
        int r = 0;
        while (j < n) {
            a = j - 1;
            head = a;
            if (emon.Port.CellsAt(tb, (a * Tbs) + 21) != 0) {
                head = emon.Port.CellsAt(tb, (a * Tbs) + 21) - 1;
            }
            if ((emon.Port.CellsAt(tb, (a * Tbs) + 0) == (emon.Port.CellsAt(tb, j * Tbs) - 1)) && (emon.Port.CellsAt(tb, (a * Tbs) + 19) == 0)) {
                ok = 1;
                if (!TbSameColumns(tb, a, j, tx)) {
                    ok = 0;
                }
                if (ok == 1) {
                    int pg0 = emon.Port.CellsAt(tb, a * Tbs);
                    int pj = emon.Port.CellsAt(tb, j * Tbs);
                    int hpa = Model.PageH(pages, pg0 - 1);
                    int hpj = Model.PageH(pages, pj - 1);
                    if (TbBodyLineOutside(ln, pg0, emon.Port.CellsAt(tb, (a * Tbs) + 4), hpa, (hpa * 8) / 100, (hpa * 92) / 100)) {
                        ok = 0;
                    }
                    if (TbBodyLineOutside(ln, pj, 0, emon.Port.CellsAt(tb, (j * Tbs) + 2), (hpj * 8) / 100, (hpj * 92) / 100)) {
                        ok = 0;
                    }
                }
                if ((ok == 1) && (emon.Port.CellsAt(tb, (j * Tbs) + 15) > 0)) {
                    if (!TbCaptionAgain(tb, head, j, wd, et, ln, tq)) {
                        ok = 0;
                    }
                }
                skip = 0;
                if ((ok == 1) && (emon.Port.CellsAt(tb, (j * Tbs) + 11) > 0)) {
                    h = emon.Port.CellsAt(tb, (head * Tbs) + 11);
                    if (h != emon.Port.CellsAt(tb, (j * Tbs) + 11)) {
                        ok = 0;
                    } else {
                        r = 0;
                        while (r < h) {
                            if (!TbRowSame(tb, head, r, j, r, tc, tw, wd, et)) {
                                ok = 0;
                            }
                            r += 1;
                        }
                        skip = h;
                    }
                }
                if (ok == 1) {
                    emon.Port.CellsSet(tb, (a * Tbs) + 19, j + 1);
                    emon.Port.CellsSet(tb, (j * Tbs) + 20, skip);
                    emon.Port.CellsSet(tb, (j * Tbs) + 21, head + 1);
                    span = (emon.Port.CellsAt(tb, j * Tbs) - emon.Port.CellsAt(tb, head * Tbs)) + 1;
                    emon.Port.CellsSet(tb, (head * Tbs) + 18, span);
                    TbUnfoot(tb, a, tc);
                }
            }
            j += 1;
        }
        return 0;
    }
    internal static int TbCellAt(emon.Port.Cells tc, int cfirst, int cend, int row, int col) {
        // The live cell whose rows and columns cover (row, col), -1 when none does.
        int c = cfirst;
        while (c < cend) {
            int cb = c * Tcs;
            if ((emon.Port.CellsAt(tc, cb + 12) & 1) == 0) {
                if ((emon.Port.CellsAt(tc, cb) <= row) && (row < (emon.Port.CellsAt(tc, cb) + emon.Port.CellsAt(tc, cb + 2)))) {
                    if ((emon.Port.CellsAt(tc, cb + 1) <= col) && (col < (emon.Port.CellsAt(tc, cb + 1) + emon.Port.CellsAt(tc, cb + 3)))) {
                        return c;
                    }
                }
            }
            c += 1;
        }
        return -1;
    }
    internal static int TbHeaderSpans(emon.Port.Cells tb, int k, emon.Port.Cells tc) {
        // Text-based tables have no rules to say where a header cell spans: a header cell whose cell below it is
        // empty spans down (the empty cell is absorbed: flag 1), and a header cell followed by empty cells over cells
        // with text spans across them. Only header rows with a header row below them are looked at.
        int b = k * Tbs;
        int nhead = emon.Port.CellsAt(tb, b + 11);
        int ncols = emon.Port.CellsAt(tb, b + 8);
        int cfirst = emon.Port.CellsAt(tb, b + 9);
        int cend = cfirst + emon.Port.CellsAt(tb, b + 10);
        int c = cfirst;
        int rs = 1;
        int j = 0;
        int y = -1;
        int more = 1;
        if (nhead < 2) {
            return 0;
        }
        while (c < cend) {
            int cb = c * Tcs;
            int r = emon.Port.CellsAt(tc, cb);
            int col = emon.Port.CellsAt(tc, cb + 1);
            if ((r < (nhead - 1)) && (((emon.Port.CellsAt(tc, cb + 12) & 1) == 0) && (emon.Port.CellsAt(tc, cb + 9) > 0))) {
                rs = 1;
                more = 1;
                while ((more == 1) && ((r + rs) < nhead)) {
                    y = TbCellAt(tc, cfirst, cend, r + rs, col);
                    if ((y >= 0) && ((emon.Port.CellsAt(tc, y * Tcs) == (r + rs)) && ((emon.Port.CellsAt(tc, (y * Tcs) + 1) == col) && ((emon.Port.CellsAt(tc, (y * Tcs) + 3) == emon.Port.CellsAt(tc, cb + 3)) && (emon.Port.CellsAt(tc, (y * Tcs) + 9) == 0))))) {
                        emon.Port.CellsSet(tc, (y * Tcs) + 12, 1);
                        rs += 1;
                    } else {
                        more = 0;
                    }
                }
                if (rs > 1) {
                    emon.Port.CellsSet(tc, cb + 2, rs);
                }
                if (emon.Port.CellsAt(tc, cb + 3) == 1) {
                    j = col + 1;
                    more = 1;
                    while ((more == 1) && (j < ncols)) {
                        int e = TbCellAt(tc, cfirst, cend, r, j);
                        int under = TbCellAt(tc, cfirst, cend, r + 1, j);
                        if ((e >= 0) && (under >= 0)) {
                            if ((emon.Port.CellsAt(tc, (e * Tcs) + 1) == j) && ((emon.Port.CellsAt(tc, (e * Tcs) + 3) == 1) && ((emon.Port.CellsAt(tc, (e * Tcs) + 9) == 0) && (emon.Port.CellsAt(tc, (under * Tcs) + 9) > 0)))) {
                                emon.Port.CellsSet(tc, (e * Tcs) + 12, 1);
                                emon.Port.CellsSet(tc, cb + 3, emon.Port.CellsAt(tc, cb + 3) + 1);
                                j += 1;
                            } else {
                                more = 0;
                            }
                        } else {
                            more = 0;
                        }
                    }
                }
            }
            c += 1;
        }
        return 0;
    }
    internal static int TbFinish(emon.Port.Cells tb, int k, emon.Port.Cells wd, emon.Port.Cells et, emon.Port.Cells tc, emon.Port.Cells tw, emon.Port.Cells ln, int l0, int l1, emon.Port.Cells tq) {
        // What the cells of table k say once they are placed (SPEC 10.5, 10.10): the header rows, the footer,
        // which cells are header cells (`col` in the header, `row` in the footer), each cell's alignment, the caption.
        int b = k * Tbs;
        int nrows = emon.Port.CellsAt(tb, b + 7);
        int cfirst = emon.Port.CellsAt(tb, b + 9);
        int cend = cfirst + emon.Port.CellsAt(tb, b + 10);
        int nhead = TbHeadRows(tb, k, wd, et, tc, tw);
        int nfoot = TbFootRows(tb, k, nhead, wd, et, tc, tw);
        int c = cfirst;
        emon.Port.CellsSet(tb, b + 11, nhead);
        emon.Port.CellsSet(tb, b + 12, nfoot);
        while (c < cend) {
            int r = emon.Port.CellsAt(tc, c * Tcs);
            if (r < nhead) {
                emon.Port.CellsSet(tc, (c * Tcs) + 10, 1);
            }
            if (r >= (nrows - nfoot)) {
                emon.Port.CellsSet(tc, (c * Tcs) + 10, 2);
            }
            c += 1;
        }
        if (emon.Port.CellsAt(tb, b + 5) != PfRuled) {
            TbHeaderSpans(tb, k, tc);
        }
        TbAligns(tb, k, wd, tc, tw);
        TbCaption(tb, k, wd, et, ln, l0, l1, tq);
        return 0;
    }
    public static int TbBuild(emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells et, emon.Port.Cells pa, int np, emon.Port.Cells tb, emon.Port.Cells tc, emon.Port.Cells tw, emon.Port.Cells tq, emon.Port.Cells tx, emon.Port.Cells s0, emon.Port.Cells s1, emon.Port.Cells s2, emon.Port.Cells s3, emon.Port.Cells s4, emon.Port.Cells s5, emon.Port.Cells s6, emon.Port.Cells s7, emon.Port.Cells s8, emon.Port.Cells s9, emon.Port.Cells s10, emon.Port.Cells s11, emon.Port.Cells s12, emon.Port.Cells s13, emon.Port.Cells s14, emon.Port.Cells s15, emon.Port.Cells s16, emon.Port.Cells s17, emon.Port.Cells s18, emon.Port.Cells pages) {
        // Find the tables of every page and claim their lines. `tb tc tw tq tx` are emptied first; s0..s18 are
        // scratch: rules, merged rules, fills, a sort order, x and y boundaries, the grid, word pairs, a copy of tb
        // rows, flags, the page's words, rows and chunks, channels, two coordinate lists, the row map, spans and
        // row extents (one name each in the calls below). Answers the number of tables.
        int nw = Evidence.WdCount(wd);
        int nl = Evidence.LnCount(ln);
        int nq = Evidence.PaCount(pa);
        int p = 1;
        int wi = 0;
        int wj = 0;
        int li = 0;
        int lj = 0;
        int qi = 0;
        int qj = 0;
        int t0 = 0;
        int k = 0;
        emon.Port.CellsDrop(tb, 0);
        emon.Port.CellsDrop(tc, 0);
        emon.Port.CellsDrop(tw, 0);
        emon.Port.CellsDrop(tq, 0);
        emon.Port.CellsDrop(tx, 0);
        while (p <= np) {
            while ((wi < nw) && (Evidence.WdGet(wd, wi, Evidence.HdPage()) < p)) {
                wi += 1;
            }
            wj = wi;
            while ((wj < nw) && (Evidence.WdGet(wd, wj, Evidence.HdPage()) == p)) {
                wj += 1;
            }
            while ((li < nl) && (Evidence.LnGet(ln, li, Evidence.LhPage()) < p)) {
                li += 1;
            }
            lj = li;
            while ((lj < nl) && (Evidence.LnGet(ln, lj, Evidence.LhPage()) == p)) {
                lj += 1;
            }
            while ((qi < nq) && (Evidence.PaGet(pa, qi, Evidence.PfPage()) < p)) {
                qi += 1;
            }
            qj = qi;
            while ((qj < nq) && (Evidence.PaGet(pa, qj, Evidence.PfPage()) == p)) {
                qj += 1;
            }
            t0 = TbRowsOf(tb, Tbs);
            if ((wj - wi) > 0) {
                TbCollect(pa, qi, qj, s0, s2);
                if (TbRowsOf(s0, Rls) <= MaxRules) {
                    TbMergeRules(s0, s1, s3, s9);
                    TbRuledPage(s1, p, s4, s5, s6, tb, tc, wd, wi, wj, s7, s3, tw, tx);
                    TbPartialPage(s1, p, wd, et, wi, wj, s9, s10, s11, s12, s13, s14, s15, s16, s6, s17, s18, s7, s3, tb, tc, tw, tx);
                }
                if (TbRowsOf(s2, 6) <= MaxRules) {
                    TbShadedPage(s2, p, wd, et, wi, wj, s8, s9, s10, s11, s12, s13, s14, s15, s16, s6, s17, s18, s7, s3, tb, tc, tw, tx);
                }
                TbWhitespacePage(p, wd, et, wi, wj, s10, s11, s12, s13, s14, s15, s16, s6, s17, s18, s7, s3, tb, tc, tw, tx);
                TbSelect(tb, t0, s3, s9, s8);
                k = t0;
                while (k < TbRowsOf(tb, Tbs)) {
                    TbFinish(tb, k, wd, et, tc, tw, ln, li, lj, tq);
                    k += 1;
                }
                TbClaim(tb, t0, ln, li, lj);
            }
            wi = wj;
            li = lj;
            qi = qj;
            p += 1;
        }
        TbLink(tb, tc, tw, tx, tq, wd, et, ln, pages);
        return TbRowsOf(tb, Tbs);
    }
}
